package com.cockpitbench.foundation.core;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/** Resumable workflow runner used by sign-in, consent, recovery, and profile migration. */
public final class WorkflowEngine {
    public enum Status {
        CREATED,
        RUNNING,
        WAITING,
        COMPLETED,
        FAILED,
        CANCELLED
    }

    public enum StepStatus {
        PENDING,
        RUNNING,
        SUCCEEDED,
        FAILED,
        SKIPPED
    }

    public interface Action {
        ActionResult execute(Context context) throws Exception;

        default void compensate(Context context) throws Exception {
        }
    }

    public interface Observer {
        void onTransition(String executionId, String stepId, StepStatus state);
    }

    public static final class ActionResult {
        public final boolean success;
        public final boolean waiting;
        public final String code;
        public final Map<String, String> outputs;

        private ActionResult(
                boolean success,
                boolean waiting,
                String code,
                Map<String, String> outputs) {
            this.success = success;
            this.waiting = waiting;
            this.code = code;
            this.outputs = Collections.unmodifiableMap(new LinkedHashMap<>(outputs));
        }

        public static ActionResult success(Map<String, String> outputs) {
            return new ActionResult(true, false, "", outputs);
        }

        public static ActionResult waiting(String code, Map<String, String> outputs) {
            return new ActionResult(false, true, require(code, "code"), outputs);
        }

        public static ActionResult failure(String code) {
            return new ActionResult(false, false, require(code, "code"), Collections.emptyMap());
        }
    }

    public static final class Step {
        public final String id;
        public final Set<String> dependencies;
        public final long timeoutMillis;
        public final boolean compensatable;
        public final Action action;

        public Step(
                String id,
                Collection<String> dependencies,
                long timeoutMillis,
                boolean compensatable,
                Action action) {
            this.id = require(id, "id");
            this.dependencies = Collections.unmodifiableSet(
                    new LinkedHashSet<>(Objects.requireNonNull(dependencies, "dependencies")));
            this.timeoutMillis = timeoutMillis;
            this.compensatable = compensatable;
            this.action = Objects.requireNonNull(action, "action");
            if (timeoutMillis <= 0) {
                throw new IllegalArgumentException("timeoutMillis must be positive");
            }
        }
    }

    public static final class Definition {
        public final String id;
        public final int revision;
        public final Map<String, Step> steps;
        private final List<String> order;

        public Definition(String id, int revision, Collection<Step> steps) {
            this.id = require(id, "id");
            this.revision = revision;
            Map<String, Step> indexed = new LinkedHashMap<>();
            for (Step step : Objects.requireNonNull(steps, "steps")) {
                if (indexed.put(step.id, step) != null) {
                    throw new IllegalArgumentException("duplicate step: " + step.id);
                }
            }
            if (indexed.isEmpty()) {
                throw new IllegalArgumentException("workflow has no steps");
            }
            validateDependencies(indexed);
            this.order = topologicalOrder(indexed);
            this.steps = Collections.unmodifiableMap(indexed);
            if (revision <= 0) {
                throw new IllegalArgumentException("revision must be positive");
            }
        }
    }

    public static final class Context {
        private final Map<String, String> values;

        Context(Map<String, String> initial) {
            values = new LinkedHashMap<>(Objects.requireNonNull(initial, "initial"));
        }

        public String get(String key) {
            return values.get(key);
        }

        public String require(String key) {
            String value = values.get(key);
            if (value == null || value.trim().isEmpty()) {
                throw new IllegalStateException("missing workflow value: " + key);
            }
            return value;
        }

        public void put(String key, String value) {
            values.put(
                    WorkflowEngine.require(key, "key"),
                    Objects.requireNonNull(value, "value"));
        }

        public Map<String, String> snapshot() {
            return Collections.unmodifiableMap(new LinkedHashMap<>(values));
        }
    }

    public static final class Execution {
        public final String id;
        public final Definition definition;
        public final Context context;
        private final Map<String, StepStatus> states = new LinkedHashMap<>();
        private final Deque<String> completed = new ArrayDeque<>();
        private Status status = Status.CREATED;
        private String waitingStep = "";
        private String errorCode = "";

        Execution(String id, Definition definition, Map<String, String> input) {
            this.id = require(id, "id");
            this.definition = Objects.requireNonNull(definition, "definition");
            this.context = new Context(input);
            for (String stepId : definition.order) {
                states.put(stepId, StepStatus.PENDING);
            }
        }

        public synchronized Status status() {
            return status;
        }

        public synchronized String waitingStep() {
            return waitingStep;
        }

        public synchronized String errorCode() {
            return errorCode;
        }

        public synchronized Map<String, StepStatus> stepStates() {
            return Collections.unmodifiableMap(new LinkedHashMap<>(states));
        }
    }

    private final CockpitClock clock;
    private final List<Observer> observers = new ArrayList<>();

    public WorkflowEngine(CockpitClock clock) {
        this.clock = Objects.requireNonNull(clock, "clock");
    }

    public synchronized void addObserver(Observer observer) {
        observers.add(Objects.requireNonNull(observer, "observer"));
    }

    public synchronized void removeObserver(Observer observer) {
        observers.remove(observer);
    }

    public Execution start(
            String executionId,
            Definition definition,
            Map<String, String> input) {
        Execution execution = new Execution(executionId, definition, input);
        runReadySteps(execution);
        return execution;
    }

    public void resume(Execution execution, String stepId, Map<String, String> values) {
        Objects.requireNonNull(execution, "execution");
        synchronized (execution) {
            if (execution.status != Status.WAITING || !execution.waitingStep.equals(stepId)) {
                throw new IllegalStateException("execution is not waiting for " + stepId);
            }
            for (Map.Entry<String, String> value : values.entrySet()) {
                execution.context.put(value.getKey(), value.getValue());
            }
            execution.states.put(stepId, StepStatus.SUCCEEDED);
            execution.completed.push(stepId);
            execution.waitingStep = "";
            execution.status = Status.RUNNING;
            notifyObservers(execution.id, stepId, StepStatus.SUCCEEDED);
        }
        runReadySteps(execution);
    }

    public void cancel(Execution execution) {
        Objects.requireNonNull(execution, "execution");
        synchronized (execution) {
            if (EnumSetTerminal.contains(execution.status)) {
                return;
            }
            compensate(execution);
            execution.status = Status.CANCELLED;
            execution.waitingStep = "";
        }
    }

    private void runReadySteps(Execution execution) {
        synchronized (execution) {
            if (EnumSetTerminal.contains(execution.status)) {
                return;
            }
            execution.status = Status.RUNNING;
            boolean progressed;
            do {
                progressed = false;
                for (String stepId : execution.definition.order) {
                    if (execution.states.get(stepId) != StepStatus.PENDING) {
                        continue;
                    }
                    Step step = execution.definition.steps.get(stepId);
                    if (!dependenciesSucceeded(step, execution.states)) {
                        continue;
                    }
                    progressed = true;
                    if (!executeStep(execution, step)) {
                        return;
                    }
                }
            } while (progressed);
            if (allSucceeded(execution.states)) {
                execution.status = Status.COMPLETED;
                return;
            }
            if (execution.status == Status.RUNNING) {
                execution.status = Status.FAILED;
                execution.errorCode = "WORKFLOW_STALLED";
                compensate(execution);
            }
        }
    }

    private boolean executeStep(Execution execution, Step step) {
        execution.states.put(step.id, StepStatus.RUNNING);
        notifyObservers(execution.id, step.id, StepStatus.RUNNING);
        long started = clock.now();
        try {
            ActionResult result = step.action.execute(execution.context);
            if (clock.now() - started > step.timeoutMillis) {
                fail(execution, step, "STEP_TIMEOUT");
                return false;
            }
            for (Map.Entry<String, String> output : result.outputs.entrySet()) {
                execution.context.put(output.getKey(), output.getValue());
            }
            if (result.waiting) {
                execution.status = Status.WAITING;
                execution.waitingStep = step.id;
                execution.errorCode = result.code;
                return false;
            }
            if (!result.success) {
                fail(execution, step, result.code);
                return false;
            }
            execution.states.put(step.id, StepStatus.SUCCEEDED);
            execution.completed.push(step.id);
            notifyObservers(execution.id, step.id, StepStatus.SUCCEEDED);
            return true;
        } catch (Exception error) {
            fail(execution, step, error.getClass().getSimpleName());
            return false;
        }
    }

    private void fail(Execution execution, Step step, String code) {
        execution.states.put(step.id, StepStatus.FAILED);
        execution.status = Status.FAILED;
        execution.errorCode = code;
        notifyObservers(execution.id, step.id, StepStatus.FAILED);
        compensate(execution);
    }

    private void compensate(Execution execution) {
        while (!execution.completed.isEmpty()) {
            String stepId = execution.completed.pop();
            Step step = execution.definition.steps.get(stepId);
            if (!step.compensatable) {
                continue;
            }
            try {
                step.action.compensate(execution.context);
            } catch (Exception ignored) {
                execution.errorCode = execution.errorCode + ":COMPENSATION_FAILED:" + stepId;
            }
        }
    }

    private synchronized void notifyObservers(
            String executionId,
            String stepId,
            StepStatus status) {
        for (Observer observer : new ArrayList<>(observers)) {
            observer.onTransition(executionId, stepId, status);
        }
    }

    private static boolean dependenciesSucceeded(
            Step step,
            Map<String, StepStatus> states) {
        for (String dependency : step.dependencies) {
            if (states.get(dependency) != StepStatus.SUCCEEDED) {
                return false;
            }
        }
        return true;
    }

    private static boolean allSucceeded(Map<String, StepStatus> states) {
        for (StepStatus state : states.values()) {
            if (state != StepStatus.SUCCEEDED && state != StepStatus.SKIPPED) {
                return false;
            }
        }
        return true;
    }

    private static void validateDependencies(Map<String, Step> steps) {
        for (Step step : steps.values()) {
            if (step.dependencies.contains(step.id)) {
                throw new IllegalArgumentException("step depends on itself: " + step.id);
            }
            for (String dependency : step.dependencies) {
                if (!steps.containsKey(dependency)) {
                    throw new IllegalArgumentException(
                            "unknown dependency " + dependency + " for " + step.id);
                }
            }
        }
    }

    private static List<String> topologicalOrder(Map<String, Step> steps) {
        List<String> result = new ArrayList<>();
        Set<String> visiting = new LinkedHashSet<>();
        Set<String> visited = new LinkedHashSet<>();
        for (String stepId : steps.keySet()) {
            visit(stepId, steps, visiting, visited, result);
        }
        return result;
    }

    private static void visit(
            String stepId,
            Map<String, Step> steps,
            Set<String> visiting,
            Set<String> visited,
            List<String> result) {
        if (visited.contains(stepId)) {
            return;
        }
        if (!visiting.add(stepId)) {
            throw new IllegalArgumentException("workflow dependency cycle at " + stepId);
        }
        for (String dependency : steps.get(stepId).dependencies) {
            visit(dependency, steps, visiting, visited, result);
        }
        visiting.remove(stepId);
        visited.add(stepId);
        result.add(stepId);
    }

    private static String require(String value, String name) {
        Objects.requireNonNull(value, name);
        if (value.trim().isEmpty()) {
            throw new IllegalArgumentException(name + " must not be empty");
        }
        return value;
    }

    private static final Set<Status> EnumSetTerminal =
            Collections.unmodifiableSet(new LinkedHashSet<>(java.util.Arrays.asList(
                    Status.COMPLETED,
                    Status.FAILED,
                    Status.CANCELLED)));
}
