package com.cockpitbench.foundation.core;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Owns session concurrency, expiry, zone transfer, and lifecycle notifications. */
public final class SessionSupervisor {
    public enum State {
        ACTIVE,
        IDLE,
        SUSPENDED,
        REAUTHENTICATION_REQUIRED,
        REVOKED,
        EXPIRED
    }

    public enum EventType {
        OPENED,
        TOUCHED,
        TRANSFERRED,
        SUSPENDED,
        REAUTHENTICATION_REQUESTED,
        REVOKED,
        EXPIRED
    }

    public interface Observer {
        void onEvent(Event event);
    }

    public static final class Limits {
        public final int maximumPerAccount;
        public final int maximumPerZone;
        public final long idleTimeoutMillis;
        public final long absoluteTimeoutMillis;
        public final long reauthenticationWindowMillis;

        public Limits(
                int maximumPerAccount,
                int maximumPerZone,
                long idleTimeoutMillis,
                long absoluteTimeoutMillis,
                long reauthenticationWindowMillis) {
            this.maximumPerAccount = maximumPerAccount;
            this.maximumPerZone = maximumPerZone;
            this.idleTimeoutMillis = idleTimeoutMillis;
            this.absoluteTimeoutMillis = absoluteTimeoutMillis;
            this.reauthenticationWindowMillis = reauthenticationWindowMillis;
            if (maximumPerAccount <= 0 || maximumPerZone <= 0) {
                throw new IllegalArgumentException("session maxima must be positive");
            }
            if (idleTimeoutMillis <= 0 || absoluteTimeoutMillis <= idleTimeoutMillis) {
                throw new IllegalArgumentException("invalid session timeouts");
            }
            if (reauthenticationWindowMillis <= 0) {
                throw new IllegalArgumentException("reauthentication window must be positive");
            }
        }
    }

    public static final class Session {
        public final String id;
        public final String accountId;
        public final int userId;
        private String zone;
        private State state;
        private final long openedAt;
        private long lastActiveAt;
        private long authenticatedAt;
        private String reason;

        Session(
                String id,
                String accountId,
                int userId,
                String zone,
                long now) {
            this.id = require(id, "id");
            this.accountId = require(accountId, "accountId");
            this.userId = userId;
            this.zone = require(zone, "zone");
            this.state = State.ACTIVE;
            this.openedAt = now;
            this.lastActiveAt = now;
            this.authenticatedAt = now;
            this.reason = "";
        }

        public synchronized String zone() {
            return zone;
        }

        public synchronized State state() {
            return state;
        }

        public synchronized long openedAt() {
            return openedAt;
        }

        public synchronized long lastActiveAt() {
            return lastActiveAt;
        }

        public synchronized String reason() {
            return reason;
        }
    }

    public static final class Event {
        public final EventType type;
        public final String sessionId;
        public final String accountId;
        public final String zone;
        public final String reason;
        public final long timestamp;

        Event(
                EventType type,
                Session session,
                String reason,
                long timestamp) {
            this.type = type;
            this.sessionId = session.id;
            this.accountId = session.accountId;
            this.zone = session.zone;
            this.reason = reason;
            this.timestamp = timestamp;
        }
    }

    private final Limits limits;
    private final Map<String, Session> sessions = new LinkedHashMap<>();
    private final List<Observer> observers = new ArrayList<>();

    public SessionSupervisor(Limits limits) {
        this.limits = Objects.requireNonNull(limits, "limits");
    }

    public synchronized void addObserver(Observer observer) {
        observers.add(Objects.requireNonNull(observer, "observer"));
    }

    public synchronized void removeObserver(Observer observer) {
        observers.remove(observer);
    }

    public synchronized Session open(
            String sessionId,
            String accountId,
            int userId,
            String zone,
            long now) {
        if (sessions.containsKey(sessionId)) {
            throw new IllegalArgumentException("duplicate session: " + sessionId);
        }
        expire(now);
        enforceCapacity(accountId, zone);
        Session session = new Session(sessionId, accountId, userId, zone, now);
        sessions.put(sessionId, session);
        publish(EventType.OPENED, session, "", now);
        return session;
    }

    public synchronized void touch(String sessionId, long now) {
        Session session = requireActive(sessionId);
        synchronized (session) {
            if (now < session.lastActiveAt) {
                throw new IllegalArgumentException("activity time moved backwards");
            }
            session.lastActiveAt = now;
            if (session.state == State.IDLE) {
                session.state = State.ACTIVE;
            }
        }
        publish(EventType.TOUCHED, session, "", now);
    }

    public synchronized void transfer(String sessionId, String targetZone, long now) {
        Session session = requireActive(sessionId);
        String normalized = require(targetZone, "targetZone");
        if (!session.zone.equals(normalized)) {
            enforceZoneCapacity(normalized);
            synchronized (session) {
                session.zone = normalized;
                session.lastActiveAt = now;
            }
            publish(EventType.TRANSFERRED, session, "zone transfer", now);
        }
    }

    public synchronized void suspend(String sessionId, String reason, long now) {
        Session session = requireActive(sessionId);
        transition(session, State.SUSPENDED, require(reason, "reason"));
        publish(EventType.SUSPENDED, session, reason, now);
    }

    public synchronized void requireReauthentication(
            String sessionId,
            String reason,
            long now) {
        Session session = requireActive(sessionId);
        transition(session, State.REAUTHENTICATION_REQUIRED, require(reason, "reason"));
        publish(EventType.REAUTHENTICATION_REQUESTED, session, reason, now);
    }

    public synchronized void reauthenticated(String sessionId, long now) {
        Session session = requireExisting(sessionId);
        synchronized (session) {
            if (session.state != State.REAUTHENTICATION_REQUIRED
                    && session.state != State.SUSPENDED) {
                throw new IllegalStateException("session did not require reauthentication");
            }
            session.state = State.ACTIVE;
            session.authenticatedAt = now;
            session.lastActiveAt = now;
            session.reason = "";
        }
        publish(EventType.TOUCHED, session, "reauthenticated", now);
    }

    public synchronized void revoke(String sessionId, String reason, long now) {
        Session session = requireExisting(sessionId);
        transition(session, State.REVOKED, require(reason, "reason"));
        publish(EventType.REVOKED, session, reason, now);
    }

    public synchronized int expire(long now) {
        int expired = 0;
        for (Session session : sessions.values()) {
            synchronized (session) {
                if (terminal(session.state)) {
                    continue;
                }
                boolean absolute = now - session.openedAt >= limits.absoluteTimeoutMillis;
                boolean idle = now - session.lastActiveAt >= limits.idleTimeoutMillis;
                boolean staleAuthentication = session.state == State.REAUTHENTICATION_REQUIRED
                        && now - session.authenticatedAt >= limits.reauthenticationWindowMillis;
                if (absolute || idle || staleAuthentication) {
                    session.state = State.EXPIRED;
                    session.reason = absolute
                            ? "absolute timeout"
                            : staleAuthentication ? "reauthentication timeout" : "idle timeout";
                    publish(EventType.EXPIRED, session, session.reason, now);
                    expired++;
                } else if (now - session.lastActiveAt >= limits.idleTimeoutMillis / 2
                        && session.state == State.ACTIVE) {
                    session.state = State.IDLE;
                }
            }
        }
        return expired;
    }

    public synchronized int removeTerminal() {
        int removed = 0;
        Iterator<Session> iterator = sessions.values().iterator();
        while (iterator.hasNext()) {
            if (terminal(iterator.next().state)) {
                iterator.remove();
                removed++;
            }
        }
        return removed;
    }

    public synchronized List<Session> snapshot() {
        List<Session> values = new ArrayList<>(sessions.values());
        values.sort(Comparator.comparing((Session value) -> value.accountId)
                .thenComparing(value -> value.zone)
                .thenComparing(value -> value.id));
        return Collections.unmodifiableList(values);
    }

    private void enforceCapacity(String accountId, String zone) {
        int accountCount = 0;
        for (Session session : sessions.values()) {
            if (!terminal(session.state) && session.accountId.equals(accountId)) {
                accountCount++;
            }
        }
        if (accountCount >= limits.maximumPerAccount) {
            throw new IllegalStateException("account session capacity reached");
        }
        enforceZoneCapacity(zone);
    }

    private void enforceZoneCapacity(String zone) {
        int zoneCount = 0;
        for (Session session : sessions.values()) {
            if (!terminal(session.state) && session.zone.equals(zone)) {
                zoneCount++;
            }
        }
        if (zoneCount >= limits.maximumPerZone) {
            throw new IllegalStateException("zone session capacity reached");
        }
    }

    private Session requireActive(String sessionId) {
        Session session = requireExisting(sessionId);
        if (terminal(session.state)) {
            throw new IllegalStateException("session is terminal");
        }
        return session;
    }

    private Session requireExisting(String sessionId) {
        Session session = sessions.get(sessionId);
        if (session == null) {
            throw new IllegalArgumentException("unknown session: " + sessionId);
        }
        return session;
    }

    private static void transition(Session session, State state, String reason) {
        synchronized (session) {
            session.state = state;
            session.reason = reason;
        }
    }

    private void publish(EventType type, Session session, String reason, long timestamp) {
        Event event = new Event(type, session, reason, timestamp);
        for (Observer observer : new ArrayList<>(observers)) {
            observer.onEvent(event);
        }
    }

    private static boolean terminal(State state) {
        return state == State.REVOKED || state == State.EXPIRED;
    }

    private static String require(String value, String name) {
        Objects.requireNonNull(value, name);
        if (value.trim().isEmpty()) {
            throw new IllegalArgumentException(name + " must not be empty");
        }
        return value;
    }
}
