package com.cockpitbench.foundation.core;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/** Field-level account reconciliation with explicit conflicts and deterministic ordering. */
public final class RecordReconciler {
    public enum Authority {
        LOCAL,
        PROVIDER,
        FLEET,
        OWNER
    }

    public enum Strategy {
        NEWEST,
        AUTHORITY,
        LOCAL_ONLY,
        REMOTE_ONLY,
        MANUAL
    }

    public static final class Value {
        public final String content;
        public final long changedAt;
        public final Authority authority;
        public final boolean tombstone;

        public Value(String content, long changedAt, Authority authority, boolean tombstone) {
            this.content = content == null ? "" : content;
            this.changedAt = changedAt;
            this.authority = Objects.requireNonNull(authority, "authority");
            this.tombstone = tombstone;
            if (changedAt < 0) {
                throw new IllegalArgumentException("changedAt must not be negative");
            }
        }

        public boolean semanticallyEquals(Value other) {
            return other != null
                    && content.equals(other.content)
                    && tombstone == other.tombstone;
        }
    }

    public static final class Record {
        public final String accountId;
        public final long revision;
        public final Map<String, Value> fields;

        public Record(String accountId, long revision, Map<String, Value> fields) {
            this.accountId = require(accountId, "accountId");
            this.revision = revision;
            this.fields = Collections.unmodifiableMap(
                    new LinkedHashMap<>(Objects.requireNonNull(fields, "fields")));
            if (revision < 0) {
                throw new IllegalArgumentException("revision must not be negative");
            }
            for (String field : this.fields.keySet()) {
                require(field, "field");
            }
        }
    }

    public static final class FieldPolicy {
        public final String field;
        public final Strategy strategy;
        public final List<Authority> authorityOrder;
        public final boolean deletionWins;

        public FieldPolicy(
                String field,
                Strategy strategy,
                Collection<Authority> authorityOrder,
                boolean deletionWins) {
            this.field = require(field, "field");
            this.strategy = Objects.requireNonNull(strategy, "strategy");
            this.authorityOrder = Collections.unmodifiableList(
                    new ArrayList<>(Objects.requireNonNull(authorityOrder, "authorityOrder")));
            this.deletionWins = deletionWins;
            if (strategy == Strategy.AUTHORITY && this.authorityOrder.isEmpty()) {
                throw new IllegalArgumentException("authority strategy needs an order");
            }
        }
    }

    public static final class Conflict {
        public final String field;
        public final Value base;
        public final Value local;
        public final Value remote;
        public final String reason;

        Conflict(String field, Value base, Value local, Value remote, String reason) {
            this.field = field;
            this.base = base;
            this.local = local;
            this.remote = remote;
            this.reason = reason;
        }
    }

    public static final class Change {
        public final String field;
        public final Value before;
        public final Value after;
        public final String source;

        Change(String field, Value before, Value after, String source) {
            this.field = field;
            this.before = before;
            this.after = after;
            this.source = source;
        }
    }

    public static final class Result {
        public final Record merged;
        public final List<Conflict> conflicts;
        public final List<Change> changes;

        Result(Record merged, List<Conflict> conflicts, List<Change> changes) {
            this.merged = merged;
            this.conflicts = Collections.unmodifiableList(new ArrayList<>(conflicts));
            this.changes = Collections.unmodifiableList(new ArrayList<>(changes));
        }

        public boolean requiresUserResolution() {
            return !conflicts.isEmpty();
        }
    }

    private final Map<String, FieldPolicy> policies;

    public RecordReconciler(Collection<FieldPolicy> policies) {
        Map<String, FieldPolicy> indexed = new LinkedHashMap<>();
        for (FieldPolicy policy : Objects.requireNonNull(policies, "policies")) {
            if (indexed.put(policy.field, policy) != null) {
                throw new IllegalArgumentException("duplicate field policy: " + policy.field);
            }
        }
        this.policies = Collections.unmodifiableMap(indexed);
    }

    public Result reconcile(Record base, Record local, Record remote) {
        validateIdentity(base, local, remote);
        Set<String> fieldNames = new LinkedHashSet<>();
        fieldNames.addAll(base.fields.keySet());
        fieldNames.addAll(local.fields.keySet());
        fieldNames.addAll(remote.fields.keySet());
        List<String> ordered = new ArrayList<>(fieldNames);
        ordered.sort(Comparator.naturalOrder());

        Map<String, Value> merged = new LinkedHashMap<>();
        List<Conflict> conflicts = new ArrayList<>();
        List<Change> changes = new ArrayList<>();
        for (String field : ordered) {
            Value baseValue = base.fields.get(field);
            Value localValue = local.fields.get(field);
            Value remoteValue = remote.fields.get(field);
            FieldPolicy policy = policies.getOrDefault(
                    field,
                    new FieldPolicy(field, Strategy.MANUAL, Collections.emptyList(), false));
            Selection selection = select(policy, baseValue, localValue, remoteValue);
            if (selection.conflictReason != null) {
                conflicts.add(new Conflict(
                        field,
                        baseValue,
                        localValue,
                        remoteValue,
                        selection.conflictReason));
            }
            if (selection.value != null && !selection.value.tombstone) {
                merged.put(field, selection.value);
            }
            if (!sameValue(baseValue, selection.value)) {
                changes.add(new Change(field, baseValue, selection.value, selection.source));
            }
        }
        long revision = Math.max(local.revision, remote.revision) + 1;
        return new Result(
                new Record(base.accountId, revision, merged),
                conflicts,
                changes);
    }

    private Selection select(
            FieldPolicy policy,
            Value base,
            Value local,
            Value remote) {
        boolean localChanged = !sameValue(base, local);
        boolean remoteChanged = !sameValue(base, remote);
        if (!localChanged && !remoteChanged) {
            return new Selection(base, "base", null);
        }
        if (localChanged && !remoteChanged) {
            return new Selection(local, "local", null);
        }
        if (!localChanged) {
            return new Selection(remote, "remote", null);
        }
        if (sameValue(local, remote)) {
            return new Selection(local, "both", null);
        }
        if (policy.deletionWins && isDeletion(local, remote)) {
            Value deletion = local != null && local.tombstone ? local : remote;
            return new Selection(deletion, "deletion", null);
        }
        switch (policy.strategy) {
            case LOCAL_ONLY:
                return new Selection(local, "local-policy", null);
            case REMOTE_ONLY:
                return new Selection(remote, "remote-policy", null);
            case NEWEST:
                return newest(local, remote);
            case AUTHORITY:
                return authoritative(policy, local, remote);
            case MANUAL:
            default:
                Value provisional = newest(local, remote).value;
                return new Selection(provisional, "provisional", "concurrent edits require review");
        }
    }

    private static Selection newest(Value local, Value remote) {
        if (local == null) {
            return new Selection(remote, "remote-newest", null);
        }
        if (remote == null) {
            return new Selection(local, "local-newest", null);
        }
        if (local.changedAt == remote.changedAt) {
            return new Selection(
                    local,
                    "local-tie-break",
                    "equal timestamps with different values");
        }
        return local.changedAt > remote.changedAt
                ? new Selection(local, "local-newest", null)
                : new Selection(remote, "remote-newest", null);
    }

    private static Selection authoritative(FieldPolicy policy, Value local, Value remote) {
        if (local == null) {
            return new Selection(remote, "remote-authority", null);
        }
        if (remote == null) {
            return new Selection(local, "local-authority", null);
        }
        int localRank = rank(policy.authorityOrder, local.authority);
        int remoteRank = rank(policy.authorityOrder, remote.authority);
        if (localRank == remoteRank) {
            Selection newest = newest(local, remote);
            return new Selection(newest.value, newest.source, "equal authority produced conflict");
        }
        return localRank < remoteRank
                ? new Selection(local, "local-authority", null)
                : new Selection(remote, "remote-authority", null);
    }

    private static int rank(List<Authority> order, Authority authority) {
        int index = order.indexOf(authority);
        return index < 0 ? Integer.MAX_VALUE : index;
    }

    private static boolean isDeletion(Value first, Value second) {
        return first != null && first.tombstone || second != null && second.tombstone;
    }

    private static boolean sameValue(Value first, Value second) {
        if (first == null) {
            return second == null;
        }
        return first.semanticallyEquals(second);
    }

    private static void validateIdentity(Record base, Record local, Record remote) {
        Objects.requireNonNull(base, "base");
        Objects.requireNonNull(local, "local");
        Objects.requireNonNull(remote, "remote");
        if (!base.accountId.equals(local.accountId) || !base.accountId.equals(remote.accountId)) {
            throw new IllegalArgumentException("cannot reconcile different accounts");
        }
        if (local.revision < base.revision || remote.revision < base.revision) {
            throw new IllegalArgumentException("branch revision precedes base");
        }
    }

    private static String require(String value, String name) {
        Objects.requireNonNull(value, name);
        if (value.trim().isEmpty()) {
            throw new IllegalArgumentException(name + " must not be empty");
        }
        return value;
    }

    private static final class Selection {
        final Value value;
        final String source;
        final String conflictReason;

        Selection(Value value, String source, String conflictReason) {
            this.value = value;
            this.source = source;
            this.conflictReason = conflictReason;
        }
    }
}

