package com.cockpitbench.foundation.core;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/** Deterministic policy evaluator for identity operations across occupants and zones. */
public final class PolicyRuntime {
    public enum Effect {
        ALLOW,
        DENY,
        REQUIRE_CONSENT,
        REQUIRE_REAUTHENTICATION
    }

    public enum Operator {
        EQUALS,
        NOT_EQUALS,
        CONTAINS,
        IN,
        GREATER_THAN,
        LESS_THAN,
        PRESENT
    }

    public static final class Condition {
        public final String attribute;
        public final Operator operator;
        public final String expected;

        public Condition(String attribute, Operator operator, String expected) {
            this.attribute = requireToken(attribute, "attribute");
            this.operator = Objects.requireNonNull(operator, "operator");
            this.expected = expected == null ? "" : expected;
        }
    }

    public static final class Rule {
        public final String id;
        public final int priority;
        public final String operation;
        public final Effect effect;
        public final List<Condition> conditions;
        public final String reason;

        public Rule(
                String id,
                int priority,
                String operation,
                Effect effect,
                Collection<Condition> conditions,
                String reason) {
            this.id = requireToken(id, "id");
            this.priority = priority;
            this.operation = requireToken(operation, "operation");
            this.effect = Objects.requireNonNull(effect, "effect");
            this.conditions = immutableList(conditions);
            this.reason = requireToken(reason, "reason");
            if (priority < 0 || priority > 10_000) {
                throw new IllegalArgumentException("priority out of range");
            }
        }
    }

    public static final class PolicySet {
        public final String id;
        public final int revision;
        public final Effect defaultEffect;
        public final List<Rule> rules;

        public PolicySet(String id, int revision, Effect defaultEffect, Collection<Rule> rules) {
            this.id = requireToken(id, "id");
            this.revision = revision;
            this.defaultEffect = Objects.requireNonNull(defaultEffect, "defaultEffect");
            List<Rule> ordered = new ArrayList<>(Objects.requireNonNull(rules, "rules"));
            ordered.sort(Comparator.comparingInt((Rule value) -> value.priority).reversed()
                    .thenComparing(value -> value.id));
            validateRuleIds(ordered);
            this.rules = Collections.unmodifiableList(ordered);
            if (revision <= 0) {
                throw new IllegalArgumentException("revision must be positive");
            }
        }
    }

    public static final class Request {
        public final String operation;
        public final String accountId;
        public final int userId;
        public final String zone;
        public final Set<String> roles;
        public final Map<String, String> attributes;

        public Request(
                String operation,
                String accountId,
                int userId,
                String zone,
                Collection<String> roles,
                Map<String, String> attributes) {
            this.operation = requireToken(operation, "operation");
            this.accountId = requireToken(accountId, "accountId");
            this.userId = userId;
            this.zone = requireToken(zone, "zone");
            this.roles = immutableSet(roles);
            this.attributes = Collections.unmodifiableMap(
                    new LinkedHashMap<>(Objects.requireNonNull(attributes, "attributes")));
        }

        public String attribute(String name) {
            switch (name) {
                case "operation":
                    return operation;
                case "accountId":
                    return accountId;
                case "userId":
                    return Integer.toString(userId);
                case "zone":
                    return zone;
                case "roles":
                    return String.join(",", roles);
                default:
                    return attributes.get(name);
            }
        }
    }

    public static final class TraceStep {
        public final String ruleId;
        public final boolean operationMatched;
        public final boolean conditionsMatched;
        public final String detail;

        TraceStep(
                String ruleId,
                boolean operationMatched,
                boolean conditionsMatched,
                String detail) {
            this.ruleId = ruleId;
            this.operationMatched = operationMatched;
            this.conditionsMatched = conditionsMatched;
            this.detail = detail;
        }
    }

    public static final class Decision {
        public final Effect effect;
        public final String reason;
        public final String ruleId;
        public final int policyRevision;
        public final List<TraceStep> trace;

        Decision(
                Effect effect,
                String reason,
                String ruleId,
                int policyRevision,
                List<TraceStep> trace) {
            this.effect = effect;
            this.reason = reason;
            this.ruleId = ruleId;
            this.policyRevision = policyRevision;
            this.trace = Collections.unmodifiableList(new ArrayList<>(trace));
        }

        public boolean permitsImmediateExecution() {
            return effect == Effect.ALLOW;
        }

        public boolean requiresUserInteraction() {
            return effect == Effect.REQUIRE_CONSENT
                    || effect == Effect.REQUIRE_REAUTHENTICATION;
        }
    }

    public Decision evaluate(PolicySet policy, Request request) {
        Objects.requireNonNull(policy, "policy");
        Objects.requireNonNull(request, "request");
        List<TraceStep> trace = new ArrayList<>();
        for (Rule rule : policy.rules) {
            boolean operationMatched = matchesOperation(rule.operation, request.operation);
            if (!operationMatched) {
                trace.add(new TraceStep(rule.id, false, false, "operation mismatch"));
                continue;
            }
            String mismatch = firstMismatch(rule.conditions, request);
            boolean conditionsMatched = mismatch == null;
            trace.add(new TraceStep(
                    rule.id,
                    true,
                    conditionsMatched,
                    conditionsMatched ? "matched" : mismatch));
            if (conditionsMatched) {
                return new Decision(
                        rule.effect,
                        rule.reason,
                        rule.id,
                        policy.revision,
                        trace);
            }
        }
        return new Decision(
                policy.defaultEffect,
                "policy default",
                "",
                policy.revision,
                trace);
    }

    public Map<String, Decision> evaluateBatch(
            PolicySet policy,
            Collection<Request> requests) {
        Map<String, Decision> decisions = new LinkedHashMap<>();
        for (Request request : Objects.requireNonNull(requests, "requests")) {
            String key = request.accountId + ":" + request.operation + ":" + request.zone;
            if (decisions.put(key, evaluate(policy, request)) != null) {
                throw new IllegalArgumentException("duplicate request key: " + key);
            }
        }
        return Collections.unmodifiableMap(decisions);
    }

    private static boolean matchesOperation(String ruleOperation, String requestedOperation) {
        return ruleOperation.equals("*") || ruleOperation.equals(requestedOperation);
    }

    private static String firstMismatch(List<Condition> conditions, Request request) {
        for (Condition condition : conditions) {
            String actual = request.attribute(condition.attribute);
            if (!matches(condition, actual)) {
                return condition.attribute + " did not satisfy "
                        + condition.operator.name().toLowerCase(Locale.ROOT);
            }
        }
        return null;
    }

    private static boolean matches(Condition condition, String actual) {
        switch (condition.operator) {
            case PRESENT:
                return actual != null && !actual.trim().isEmpty();
            case EQUALS:
                return Objects.equals(actual, condition.expected);
            case NOT_EQUALS:
                return !Objects.equals(actual, condition.expected);
            case CONTAINS:
                return actual != null && containsToken(actual, condition.expected);
            case IN:
                return actual != null && containsToken(condition.expected, actual);
            case GREATER_THAN:
                return compareNumbers(actual, condition.expected) > 0;
            case LESS_THAN:
                return compareNumbers(actual, condition.expected) < 0;
            default:
                throw new IllegalStateException("unsupported operator: " + condition.operator);
        }
    }

    private static boolean containsToken(String values, String expected) {
        for (String token : values.split(",")) {
            if (token.trim().equals(expected)) {
                return true;
            }
        }
        return false;
    }

    private static int compareNumbers(String actual, String expected) {
        if (actual == null) {
            return Integer.MIN_VALUE;
        }
        try {
            return Double.compare(Double.parseDouble(actual), Double.parseDouble(expected));
        } catch (NumberFormatException error) {
            return Integer.MIN_VALUE;
        }
    }

    private static void validateRuleIds(List<Rule> rules) {
        Set<String> ids = new LinkedHashSet<>();
        for (Rule rule : rules) {
            if (!ids.add(rule.id)) {
                throw new IllegalArgumentException("duplicate rule id: " + rule.id);
            }
        }
    }

    private static String requireToken(String value, String name) {
        Objects.requireNonNull(value, name);
        if (value.trim().isEmpty()) {
            throw new IllegalArgumentException(name + " must not be empty");
        }
        return value;
    }

    private static <T> List<T> immutableList(Collection<T> values) {
        return Collections.unmodifiableList(
                new ArrayList<>(Objects.requireNonNull(values, "values")));
    }

    private static <T> Set<T> immutableSet(Collection<T> values) {
        return Collections.unmodifiableSet(
                new LinkedHashSet<>(Objects.requireNonNull(values, "values")));
    }
}
