package com.cockpitbench.foundation.core;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/** Resolves inherited cockpit roles with deny precedence and zone constraints. */
public final class RoleAuthorizationGraph {
    public enum Effect {
        ALLOW,
        DENY
    }

    public static final class Permission {
        public final String operation;
        public final Effect effect;
        public final Set<String> zones;
        public final boolean recentAuthenticationRequired;

        public Permission(
                String operation,
                Effect effect,
                Collection<String> zones,
                boolean recentAuthenticationRequired) {
            this.operation = require(operation, "operation");
            this.effect = Objects.requireNonNull(effect, "effect");
            this.zones = immutableSet(zones);
            this.recentAuthenticationRequired = recentAuthenticationRequired;
            if (this.zones.isEmpty()) {
                throw new IllegalArgumentException("permission needs a zone");
            }
        }
    }

    public static final class Role {
        public final String id;
        public final Set<String> parents;
        public final List<Permission> permissions;
        public final boolean assignable;

        public Role(
                String id,
                Collection<String> parents,
                Collection<Permission> permissions,
                boolean assignable) {
            this.id = require(id, "id");
            this.parents = immutableSet(parents);
            this.permissions = Collections.unmodifiableList(
                    new ArrayList<>(Objects.requireNonNull(permissions, "permissions")));
            this.assignable = assignable;
            if (this.parents.contains(id)) {
                throw new IllegalArgumentException("role cannot inherit itself");
            }
        }
    }

    public static final class Assignment {
        public final String roleId;
        public final String zone;
        public final long validFrom;
        public final long validUntil;
        public final String source;

        public Assignment(
                String roleId,
                String zone,
                long validFrom,
                long validUntil,
                String source) {
            this.roleId = require(roleId, "roleId");
            this.zone = require(zone, "zone");
            this.validFrom = validFrom;
            this.validUntil = validUntil;
            this.source = require(source, "source");
            if (validFrom < 0 || validUntil <= validFrom) {
                throw new IllegalArgumentException("invalid assignment interval");
            }
        }
    }

    public static final class Trace {
        public final String roleId;
        public final String operation;
        public final Effect effect;
        public final boolean zoneMatched;
        public final boolean authenticationSatisfied;

        Trace(
                String roleId,
                String operation,
                Effect effect,
                boolean zoneMatched,
                boolean authenticationSatisfied) {
            this.roleId = roleId;
            this.operation = operation;
            this.effect = effect;
            this.zoneMatched = zoneMatched;
            this.authenticationSatisfied = authenticationSatisfied;
        }
    }

    public static final class Decision {
        public final boolean allowed;
        public final boolean reauthenticationRequired;
        public final String reason;
        public final List<String> effectiveRoles;
        public final List<Trace> trace;

        Decision(
                boolean allowed,
                boolean reauthenticationRequired,
                String reason,
                List<String> effectiveRoles,
                List<Trace> trace) {
            this.allowed = allowed;
            this.reauthenticationRequired = reauthenticationRequired;
            this.reason = reason;
            this.effectiveRoles = Collections.unmodifiableList(
                    new ArrayList<>(effectiveRoles));
            this.trace = Collections.unmodifiableList(new ArrayList<>(trace));
        }
    }

    private final Map<String, Role> roles;

    public RoleAuthorizationGraph(Collection<Role> roles) {
        Map<String, Role> indexed = new LinkedHashMap<>();
        for (Role role : Objects.requireNonNull(roles, "roles")) {
            if (indexed.put(role.id, role) != null) {
                throw new IllegalArgumentException("duplicate role: " + role.id);
            }
        }
        validateParents(indexed);
        validateAcyclic(indexed);
        this.roles = Collections.unmodifiableMap(indexed);
    }

    public Decision authorize(
            Collection<Assignment> assignments,
            String operation,
            String zone,
            boolean recentlyAuthenticated,
            long now) {
        String requestedOperation = require(operation, "operation");
        String requestedZone = require(zone, "zone");
        Set<String> active = new LinkedHashSet<>();
        for (Assignment assignment : Objects.requireNonNull(assignments, "assignments")) {
            Role role = roles.get(assignment.roleId);
            if (role == null || !role.assignable) {
                continue;
            }
            if (assignment.validFrom <= now && assignment.validUntil > now
                    && zoneMatches(assignment.zone, requestedZone)) {
                collectRole(assignment.roleId, active);
            }
        }
        List<String> orderedRoles = new ArrayList<>(active);
        Collections.sort(orderedRoles);
        List<Trace> trace = new ArrayList<>();
        boolean allowed = false;
        boolean reauthenticationRequired = false;
        for (String roleId : orderedRoles) {
            Role role = roles.get(roleId);
            for (Permission permission : role.permissions) {
                if (!permission.operation.equals(requestedOperation)
                        && !permission.operation.equals("*")) {
                    continue;
                }
                boolean zoneMatched = permission.zones.contains("all")
                        || permission.zones.contains(requestedZone);
                boolean authenticationSatisfied = !permission.recentAuthenticationRequired
                        || recentlyAuthenticated;
                trace.add(new Trace(
                        roleId,
                        permission.operation,
                        permission.effect,
                        zoneMatched,
                        authenticationSatisfied));
                if (!zoneMatched) {
                    continue;
                }
                if (permission.effect == Effect.DENY) {
                    return new Decision(
                            false,
                            false,
                            "explicit deny from " + roleId,
                            orderedRoles,
                            trace);
                }
                if (!authenticationSatisfied) {
                    reauthenticationRequired = true;
                    continue;
                }
                allowed = true;
            }
        }
        if (allowed) {
            return new Decision(true, false, "allowed by effective role", orderedRoles, trace);
        }
        if (reauthenticationRequired) {
            return new Decision(
                    false,
                    true,
                    "recent authentication required",
                    orderedRoles,
                    trace);
        }
        return new Decision(false, false, "no matching grant", orderedRoles, trace);
    }

    public List<String> inheritanceOrder(String roleId) {
        if (!roles.containsKey(roleId)) {
            throw new IllegalArgumentException("unknown role: " + roleId);
        }
        Set<String> collected = new LinkedHashSet<>();
        collectRole(roleId, collected);
        List<String> result = new ArrayList<>(collected);
        Collections.reverse(result);
        return Collections.unmodifiableList(result);
    }

    public Map<String, List<String>> describeGraph() {
        Map<String, List<String>> result = new LinkedHashMap<>();
        List<String> ids = new ArrayList<>(roles.keySet());
        Collections.sort(ids);
        for (String id : ids) {
            List<String> parents = new ArrayList<>(roles.get(id).parents);
            Collections.sort(parents);
            result.put(id, Collections.unmodifiableList(parents));
        }
        return Collections.unmodifiableMap(result);
    }

    private void collectRole(String roleId, Set<String> collected) {
        if (!collected.add(roleId)) {
            return;
        }
        List<String> parents = new ArrayList<>(roles.get(roleId).parents);
        Collections.sort(parents);
        for (String parent : parents) {
            collectRole(parent, collected);
        }
    }

    private static boolean zoneMatches(String assignmentZone, String requestedZone) {
        return assignmentZone.equals("all") || assignmentZone.equals(requestedZone);
    }

    private static void validateParents(Map<String, Role> roles) {
        for (Role role : roles.values()) {
            for (String parent : role.parents) {
                if (!roles.containsKey(parent)) {
                    throw new IllegalArgumentException(
                            "unknown parent " + parent + " for " + role.id);
                }
            }
        }
    }

    private static void validateAcyclic(Map<String, Role> roles) {
        Set<String> visited = new LinkedHashSet<>();
        Set<String> visiting = new LinkedHashSet<>();
        for (String roleId : roles.keySet()) {
            visit(roleId, roles, visiting, visited);
        }
    }

    private static void visit(
            String roleId,
            Map<String, Role> roles,
            Set<String> visiting,
            Set<String> visited) {
        if (visited.contains(roleId)) {
            return;
        }
        if (!visiting.add(roleId)) {
            throw new IllegalArgumentException("role inheritance cycle at " + roleId);
        }
        List<String> parents = new ArrayList<>(roles.get(roleId).parents);
        parents.sort(Comparator.naturalOrder());
        for (String parent : parents) {
            visit(parent, roles, visiting, visited);
        }
        visiting.remove(roleId);
        visited.add(roleId);
    }

    private static Set<String> immutableSet(Collection<String> values) {
        return Collections.unmodifiableSet(
                new LinkedHashSet<>(Objects.requireNonNull(values, "values")));
    }

    private static String require(String value, String name) {
        Objects.requireNonNull(value, name);
        if (value.trim().isEmpty()) {
            throw new IllegalArgumentException(name + " must not be empty");
        }
        return value;
    }
}
