package com.cockpitbench.foundation.core;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Per-provider rolling health window and circuit breaker for authentication calls. */
public final class ProviderHealthMonitor {
    public enum CircuitState {
        CLOSED,
        OPEN,
        HALF_OPEN
    }

    public enum Outcome {
        SUCCESS,
        TIMEOUT,
        AUTHENTICATION_REJECTED,
        PROVIDER_ERROR,
        NETWORK_ERROR,
        CANCELLED
    }

    public static final class Config {
        public final int windowSize;
        public final int minimumSamples;
        public final double failureRateThreshold;
        public final long latencyThresholdMillis;
        public final long openDurationMillis;
        public final int halfOpenSuccesses;

        public Config(
                int windowSize,
                int minimumSamples,
                double failureRateThreshold,
                long latencyThresholdMillis,
                long openDurationMillis,
                int halfOpenSuccesses) {
            this.windowSize = windowSize;
            this.minimumSamples = minimumSamples;
            this.failureRateThreshold = failureRateThreshold;
            this.latencyThresholdMillis = latencyThresholdMillis;
            this.openDurationMillis = openDurationMillis;
            this.halfOpenSuccesses = halfOpenSuccesses;
            if (windowSize <= 0 || minimumSamples <= 0 || minimumSamples > windowSize) {
                throw new IllegalArgumentException("invalid sample window");
            }
            if (failureRateThreshold <= 0 || failureRateThreshold > 1) {
                throw new IllegalArgumentException("invalid failure threshold");
            }
            if (latencyThresholdMillis <= 0 || openDurationMillis <= 0) {
                throw new IllegalArgumentException("durations must be positive");
            }
            if (halfOpenSuccesses <= 0) {
                throw new IllegalArgumentException("half-open successes must be positive");
            }
        }
    }

    public static final class Sample {
        public final Outcome outcome;
        public final long latencyMillis;
        public final long timestamp;

        public Sample(Outcome outcome, long latencyMillis, long timestamp) {
            this.outcome = Objects.requireNonNull(outcome, "outcome");
            this.latencyMillis = latencyMillis;
            this.timestamp = timestamp;
            if (latencyMillis < 0 || timestamp < 0) {
                throw new IllegalArgumentException("sample values must not be negative");
            }
        }

        public boolean failed() {
            return outcome == Outcome.TIMEOUT
                    || outcome == Outcome.PROVIDER_ERROR
                    || outcome == Outcome.NETWORK_ERROR;
        }
    }

    public static final class Health {
        public final String providerId;
        public final CircuitState state;
        public final int samples;
        public final int failures;
        public final double failureRate;
        public final long medianLatencyMillis;
        public final long percentile95LatencyMillis;
        public final long openUntil;

        Health(
                String providerId,
                CircuitState state,
                int samples,
                int failures,
                double failureRate,
                long medianLatencyMillis,
                long percentile95LatencyMillis,
                long openUntil) {
            this.providerId = providerId;
            this.state = state;
            this.samples = samples;
            this.failures = failures;
            this.failureRate = failureRate;
            this.medianLatencyMillis = medianLatencyMillis;
            this.percentile95LatencyMillis = percentile95LatencyMillis;
            this.openUntil = openUntil;
        }
    }

    private static final class ProviderState {
        final String providerId;
        final Deque<Sample> samples = new ArrayDeque<>();
        CircuitState circuit = CircuitState.CLOSED;
        long openUntil;
        int halfOpenSuccesses;
        boolean halfOpenProbeInFlight;

        ProviderState(String providerId) {
            this.providerId = providerId;
        }
    }

    private final Config config;
    private final Map<String, ProviderState> providers = new LinkedHashMap<>();

    public ProviderHealthMonitor(Config config) {
        this.config = Objects.requireNonNull(config, "config");
    }

    public synchronized boolean acquire(String providerId, long now) {
        ProviderState state = state(providerId);
        refreshCircuit(state, now);
        if (state.circuit == CircuitState.OPEN) {
            return false;
        }
        if (state.circuit == CircuitState.HALF_OPEN) {
            if (state.halfOpenProbeInFlight) {
                return false;
            }
            state.halfOpenProbeInFlight = true;
        }
        return true;
    }

    public synchronized void record(String providerId, Sample sample) {
        ProviderState state = state(providerId);
        state.samples.addLast(Objects.requireNonNull(sample, "sample"));
        while (state.samples.size() > config.windowSize) {
            state.samples.removeFirst();
        }
        if (state.circuit == CircuitState.HALF_OPEN) {
            state.halfOpenProbeInFlight = false;
            if (sample.failed()) {
                open(state, sample.timestamp);
                return;
            }
            state.halfOpenSuccesses++;
            if (state.halfOpenSuccesses >= config.halfOpenSuccesses) {
                close(state);
            }
            return;
        }
        if (state.circuit == CircuitState.CLOSED && unhealthy(state)) {
            open(state, sample.timestamp);
        }
    }

    public synchronized Health health(String providerId, long now) {
        ProviderState state = state(providerId);
        refreshCircuit(state, now);
        List<Long> latencies = new ArrayList<>();
        int failures = 0;
        for (Sample sample : state.samples) {
            latencies.add(sample.latencyMillis);
            if (sample.failed()) {
                failures++;
            }
        }
        Collections.sort(latencies);
        double failureRate = state.samples.isEmpty()
                ? 0
                : failures / (double) state.samples.size();
        return new Health(
                providerId,
                state.circuit,
                state.samples.size(),
                failures,
                failureRate,
                percentile(latencies, 0.50),
                percentile(latencies, 0.95),
                state.openUntil);
    }

    public synchronized List<Health> snapshot(long now) {
        List<Health> result = new ArrayList<>();
        for (String providerId : providers.keySet()) {
            result.add(health(providerId, now));
        }
        result.sort(Comparator.comparing(value -> value.providerId));
        return Collections.unmodifiableList(result);
    }

    public synchronized void reset(String providerId) {
        ProviderState state = state(providerId);
        state.samples.clear();
        close(state);
    }

    private ProviderState state(String providerId) {
        String id = require(providerId, "providerId");
        return providers.computeIfAbsent(id, ProviderState::new);
    }

    private boolean unhealthy(ProviderState state) {
        if (state.samples.size() < config.minimumSamples) {
            return false;
        }
        int failures = 0;
        List<Long> latencies = new ArrayList<>();
        for (Sample sample : state.samples) {
            if (sample.failed()) {
                failures++;
            }
            latencies.add(sample.latencyMillis);
        }
        Collections.sort(latencies);
        double failureRate = failures / (double) state.samples.size();
        return failureRate >= config.failureRateThreshold
                || percentile(latencies, 0.95) >= config.latencyThresholdMillis;
    }

    private void refreshCircuit(ProviderState state, long now) {
        if (state.circuit == CircuitState.OPEN && state.openUntil <= now) {
            state.circuit = CircuitState.HALF_OPEN;
            state.halfOpenProbeInFlight = false;
            state.halfOpenSuccesses = 0;
        }
    }

    private void open(ProviderState state, long now) {
        state.circuit = CircuitState.OPEN;
        state.openUntil = now + config.openDurationMillis;
        state.halfOpenProbeInFlight = false;
        state.halfOpenSuccesses = 0;
    }

    private static void close(ProviderState state) {
        state.circuit = CircuitState.CLOSED;
        state.openUntil = 0;
        state.halfOpenProbeInFlight = false;
        state.halfOpenSuccesses = 0;
    }

    private static long percentile(List<Long> ordered, double percentile) {
        if (ordered.isEmpty()) {
            return 0;
        }
        int index = (int) Math.ceil(percentile * ordered.size()) - 1;
        return ordered.get(Math.max(0, Math.min(index, ordered.size() - 1)));
    }

    private static String require(String value, String name) {
        Objects.requireNonNull(value, name);
        if (value.trim().isEmpty()) {
            throw new IllegalArgumentException(name + " must not be empty");
        }
        return value;
    }
}

