package com.cockpitbench.foundation.core;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/** Centralizes cross-user and occupant-zone access before Binder work is dispatched. */
public final class CrossUserAccessBoundary {
    public enum Scope {
        SELF,
        CURRENT_OCCUPANT,
        SAME_ZONE,
        ANY_OCCUPANT,
        SYSTEM
    }

    public enum Outcome {
        ALLOW,
        DENY,
        REQUIRE_USER_CONFIRMATION,
        REQUIRE_SYSTEM_DELEGATION
    }

    public static final class Caller {
        public final int uid;
        public final int userId;
        public final String packageName;
        public final String zone;
        public final Set<String> permissions;
        public final boolean systemUid;

        public Caller(
                int uid,
                int userId,
                String packageName,
                String zone,
                Collection<String> permissions,
                boolean systemUid) {
            this.uid = uid;
            this.userId = userId;
            this.packageName = require(packageName, "packageName");
            this.zone = require(zone, "zone");
            this.permissions = immutableSet(permissions);
            this.systemUid = systemUid;
            if (uid < 0 || userId < 0) {
                throw new IllegalArgumentException("caller identifiers must not be negative");
            }
        }
    }

    public static final class Target {
        public final int userId;
        public final String accountId;
        public final String zone;
        public final boolean activeOccupant;

        public Target(int userId, String accountId, String zone, boolean activeOccupant) {
            this.userId = userId;
            this.accountId = require(accountId, "accountId");
            this.zone = require(zone, "zone");
            this.activeOccupant = activeOccupant;
            if (userId < 0) {
                throw new IllegalArgumentException("target user must not be negative");
            }
        }
    }

    public static final class Rule {
        public final String operation;
        public final Scope scope;
        public final Set<String> requiredPermissions;
        public final boolean confirmationForInactiveOccupant;
        public final boolean denyWhileDriving;

        public Rule(
                String operation,
                Scope scope,
                Collection<String> requiredPermissions,
                boolean confirmationForInactiveOccupant,
                boolean denyWhileDriving) {
            this.operation = require(operation, "operation");
            this.scope = Objects.requireNonNull(scope, "scope");
            this.requiredPermissions = immutableSet(requiredPermissions);
            this.confirmationForInactiveOccupant = confirmationForInactiveOccupant;
            this.denyWhileDriving = denyWhileDriving;
        }
    }

    public static final class Request {
        public final Caller caller;
        public final Target target;
        public final String operation;
        public final boolean vehicleMoving;
        public final boolean userConfirmed;
        public final String delegationToken;

        public Request(
                Caller caller,
                Target target,
                String operation,
                boolean vehicleMoving,
                boolean userConfirmed,
                String delegationToken) {
            this.caller = Objects.requireNonNull(caller, "caller");
            this.target = Objects.requireNonNull(target, "target");
            this.operation = require(operation, "operation");
            this.vehicleMoving = vehicleMoving;
            this.userConfirmed = userConfirmed;
            this.delegationToken = delegationToken == null ? "" : delegationToken;
        }
    }

    public static final class Decision {
        public final Outcome outcome;
        public final String reason;
        public final Rule rule;
        public final List<String> missingPermissions;
        public final boolean crossUser;
        public final boolean crossZone;

        Decision(
                Outcome outcome,
                String reason,
                Rule rule,
                List<String> missingPermissions,
                boolean crossUser,
                boolean crossZone) {
            this.outcome = outcome;
            this.reason = reason;
            this.rule = rule;
            this.missingPermissions = Collections.unmodifiableList(
                    new ArrayList<>(missingPermissions));
            this.crossUser = crossUser;
            this.crossZone = crossZone;
        }

        public boolean allowed() {
            return outcome == Outcome.ALLOW;
        }
    }

    private final Map<String, Rule> rules;
    private final Set<String> validDelegations = new LinkedHashSet<>();

    public CrossUserAccessBoundary(Collection<Rule> rules) {
        Map<String, Rule> indexed = new LinkedHashMap<>();
        for (Rule rule : Objects.requireNonNull(rules, "rules")) {
            if (indexed.put(rule.operation, rule) != null) {
                throw new IllegalArgumentException("duplicate operation rule: " + rule.operation);
            }
        }
        this.rules = Collections.unmodifiableMap(indexed);
    }

    public synchronized void registerDelegation(String token) {
        validDelegations.add(require(token, "token"));
    }

    public synchronized void revokeDelegation(String token) {
        validDelegations.remove(token);
    }

    public synchronized Decision evaluate(Request request) {
        Rule rule = rules.get(request.operation);
        boolean crossUser = request.caller.userId != request.target.userId;
        boolean crossZone = !request.caller.zone.equals(request.target.zone);
        if (rule == null) {
            return decision(Outcome.DENY, "operation has no policy", null, crossUser, crossZone);
        }
        if (rule.denyWhileDriving && request.vehicleMoving) {
            return decision(Outcome.DENY, "operation blocked while driving", rule, crossUser, crossZone);
        }
        List<String> missing = new ArrayList<>();
        for (String permission : rule.requiredPermissions) {
            if (!request.caller.permissions.contains(permission)) {
                missing.add(permission);
            }
        }
        Collections.sort(missing);
        if (!missing.isEmpty() && !request.caller.systemUid) {
            return new Decision(
                    Outcome.DENY,
                    "required permission missing",
                    rule,
                    missing,
                    crossUser,
                    crossZone);
        }
        Outcome scopeOutcome = checkScope(rule.scope, request, crossUser, crossZone);
        if (scopeOutcome != Outcome.ALLOW) {
            return decision(scopeOutcome, "requested scope exceeded", rule, crossUser, crossZone);
        }
        if (rule.confirmationForInactiveOccupant
                && !request.target.activeOccupant
                && !request.userConfirmed) {
            return decision(
                    Outcome.REQUIRE_USER_CONFIRMATION,
                    "inactive occupant confirmation required",
                    rule,
                    crossUser,
                    crossZone);
        }
        return decision(Outcome.ALLOW, "policy satisfied", rule, crossUser, crossZone);
    }

    private Outcome checkScope(
            Scope scope,
            Request request,
            boolean crossUser,
            boolean crossZone) {
        switch (scope) {
            case SELF:
                return crossUser ? Outcome.DENY : Outcome.ALLOW;
            case CURRENT_OCCUPANT:
                return request.target.activeOccupant ? Outcome.ALLOW : Outcome.DENY;
            case SAME_ZONE:
                return crossZone ? Outcome.DENY : Outcome.ALLOW;
            case ANY_OCCUPANT:
                if (!crossUser) {
                    return Outcome.ALLOW;
                }
                return validDelegations.contains(request.delegationToken)
                        ? Outcome.ALLOW
                        : Outcome.REQUIRE_SYSTEM_DELEGATION;
            case SYSTEM:
                return request.caller.systemUid ? Outcome.ALLOW : Outcome.DENY;
            default:
                throw new IllegalStateException("unsupported scope: " + scope);
        }
    }

    private static Decision decision(
            Outcome outcome,
            String reason,
            Rule rule,
            boolean crossUser,
            boolean crossZone) {
        return new Decision(
                outcome,
                reason,
                rule,
                Collections.emptyList(),
                crossUser,
                crossZone);
    }

    private static Set<String> immutableSet(Collection<String> values) {
        return Collections.unmodifiableSet(
                new LinkedHashSet<>(Objects.requireNonNull(values, "values")));
    }

    private static String require(String value, String name) {
        Objects.requireNonNull(value, name);
        if (value.trim().isEmpty()) {
            throw new IllegalArgumentException(name + " must not be empty");
        }
        return value;
    }
}
