package com.cockpitbench.foundation.core;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/** Evaluates bound-device evidence without leaking provider-specific details into sessions. */
public final class DeviceTrustEngine {
    public enum SignalKind {
        HARDWARE_ATTESTATION,
        SECURE_CHANNEL,
        RECENT_OWNER_APPROVAL,
        PROXIMITY,
        BIOMETRIC,
        COMPANION_APP,
        VEHICLE_KEY,
        NETWORK_REPUTATION,
        CLOCK_INTEGRITY,
        TAMPER_DETECTION
    }

    public enum Verdict {
        TRUSTED,
        LIMITED,
        CHALLENGE_REQUIRED,
        REJECTED
    }

    public static final class Signal {
        public final SignalKind kind;
        public final boolean passed;
        public final int confidence;
        public final long observedAt;
        public final String source;

        public Signal(
                SignalKind kind,
                boolean passed,
                int confidence,
                long observedAt,
                String source) {
            this.kind = Objects.requireNonNull(kind, "kind");
            this.passed = passed;
            this.confidence = confidence;
            this.observedAt = observedAt;
            this.source = require(source, "source");
            if (confidence < 0 || confidence > 100) {
                throw new IllegalArgumentException("confidence out of range");
            }
            if (observedAt < 0) {
                throw new IllegalArgumentException("observedAt must not be negative");
            }
        }
    }

    public static final class Policy {
        public final String id;
        public final long maximumAgeMillis;
        public final int trustedThreshold;
        public final int limitedThreshold;
        public final Set<SignalKind> required;
        public final Map<SignalKind, Integer> weights;
        public final boolean rejectTamper;

        public Policy(
                String id,
                long maximumAgeMillis,
                int trustedThreshold,
                int limitedThreshold,
                Collection<SignalKind> required,
                Map<SignalKind, Integer> weights,
                boolean rejectTamper) {
            this.id = require(id, "id");
            this.maximumAgeMillis = maximumAgeMillis;
            this.trustedThreshold = trustedThreshold;
            this.limitedThreshold = limitedThreshold;
            this.required = Collections.unmodifiableSet(
                    EnumSet.copyOf(Objects.requireNonNull(required, "required")));
            this.weights = Collections.unmodifiableMap(
                    new EnumMap<>(Objects.requireNonNull(weights, "weights")));
            this.rejectTamper = rejectTamper;
            if (maximumAgeMillis <= 0) {
                throw new IllegalArgumentException("maximumAgeMillis must be positive");
            }
            if (trustedThreshold <= limitedThreshold) {
                throw new IllegalArgumentException("trusted threshold must exceed limited threshold");
            }
            for (Integer weight : this.weights.values()) {
                if (weight == null || weight < -100 || weight > 100) {
                    throw new IllegalArgumentException("signal weight out of range");
                }
            }
        }
    }

    public static final class EvidenceResult {
        public final Signal signal;
        public final boolean fresh;
        public final int contribution;
        public final String detail;

        EvidenceResult(Signal signal, boolean fresh, int contribution, String detail) {
            this.signal = signal;
            this.fresh = fresh;
            this.contribution = contribution;
            this.detail = detail;
        }
    }

    public static final class Assessment {
        public final String policyId;
        public final Verdict verdict;
        public final int score;
        public final List<SignalKind> missingRequired;
        public final List<EvidenceResult> evidence;
        public final long evaluatedAt;

        Assessment(
                String policyId,
                Verdict verdict,
                int score,
                List<SignalKind> missingRequired,
                List<EvidenceResult> evidence,
                long evaluatedAt) {
            this.policyId = policyId;
            this.verdict = verdict;
            this.score = score;
            this.missingRequired = Collections.unmodifiableList(
                    new ArrayList<>(missingRequired));
            this.evidence = Collections.unmodifiableList(new ArrayList<>(evidence));
            this.evaluatedAt = evaluatedAt;
        }

        public boolean permitsCredentialRelease() {
            return verdict == Verdict.TRUSTED;
        }

        public boolean permitsLimitedSession() {
            return verdict == Verdict.TRUSTED || verdict == Verdict.LIMITED;
        }
    }

    public Assessment assess(Policy policy, Collection<Signal> signals, long now) {
        Objects.requireNonNull(policy, "policy");
        if (now < 0) {
            throw new IllegalArgumentException("now must not be negative");
        }
        Map<SignalKind, Signal> newest = newestSignals(signals);
        List<EvidenceResult> evidence = new ArrayList<>();
        List<SignalKind> missing = new ArrayList<>();
        int score = 0;
        boolean tamperDetected = false;

        for (SignalKind kind : SignalKind.values()) {
            Signal signal = newest.get(kind);
            if (signal == null) {
                if (policy.required.contains(kind)) {
                    missing.add(kind);
                }
                continue;
            }
            long age = Math.max(0, now - signal.observedAt);
            boolean fresh = age <= policy.maximumAgeMillis;
            int configuredWeight = policy.weights.getOrDefault(kind, 0);
            int confidenceAdjusted = configuredWeight * signal.confidence / 100;
            int contribution = signal.passed && fresh
                    ? confidenceAdjusted
                    : -Math.abs(confidenceAdjusted);
            score += contribution;
            if (kind == SignalKind.TAMPER_DETECTION && !signal.passed && fresh) {
                tamperDetected = true;
            }
            if (policy.required.contains(kind) && (!signal.passed || !fresh)) {
                missing.add(kind);
            }
            evidence.add(new EvidenceResult(
                    signal,
                    fresh,
                    contribution,
                    detail(signal, fresh, age)));
        }

        score = Math.max(-100, Math.min(100, score));
        missing.sort(Comparator.comparing(Enum::name));
        evidence.sort(Comparator.comparing(value -> value.signal.kind.name()));
        Verdict verdict = verdict(policy, score, missing, tamperDetected);
        return new Assessment(policy.id, verdict, score, missing, evidence, now);
    }

    public Map<String, Assessment> assessFleet(
            Policy policy,
            Map<String, ? extends Collection<Signal>> fleetEvidence,
            long now) {
        Map<String, Assessment> results = new LinkedHashMap<>();
        List<String> ids = new ArrayList<>(fleetEvidence.keySet());
        Collections.sort(ids);
        for (String deviceId : ids) {
            results.put(deviceId, assess(policy, fleetEvidence.get(deviceId), now));
        }
        return Collections.unmodifiableMap(results);
    }

    private static Map<SignalKind, Signal> newestSignals(Collection<Signal> signals) {
        Map<SignalKind, Signal> newest = new EnumMap<>(SignalKind.class);
        for (Signal signal : Objects.requireNonNull(signals, "signals")) {
            Signal current = newest.get(signal.kind);
            if (current == null || signal.observedAt > current.observedAt) {
                newest.put(signal.kind, signal);
            }
        }
        return newest;
    }

    private static Verdict verdict(
            Policy policy,
            int score,
            List<SignalKind> missing,
            boolean tamperDetected) {
        if (policy.rejectTamper && tamperDetected) {
            return Verdict.REJECTED;
        }
        if (!missing.isEmpty()) {
            return score >= policy.limitedThreshold
                    ? Verdict.CHALLENGE_REQUIRED
                    : Verdict.REJECTED;
        }
        if (score >= policy.trustedThreshold) {
            return Verdict.TRUSTED;
        }
        if (score >= policy.limitedThreshold) {
            return Verdict.LIMITED;
        }
        return Verdict.CHALLENGE_REQUIRED;
    }

    private static String detail(Signal signal, boolean fresh, long age) {
        if (!fresh) {
            return "stale:" + age;
        }
        if (!signal.passed) {
            return "failed:" + signal.source;
        }
        return "accepted:" + signal.source;
    }

    private static String require(String value, String name) {
        Objects.requireNonNull(value, name);
        if (value.trim().isEmpty()) {
            throw new IllegalArgumentException(name + " must not be empty");
        }
        return value;
    }
