import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Produces deterministic retention actions for identity audit partitions. */
public final class AuditRetentionPlanner {
    public enum Category {
        AUTHENTICATION,
        ACCOUNT_CHANGE,
        CONSENT_CHANGE,
        ROLE_CHANGE,
        DEVICE_BINDING,
        SECURITY_ALERT,
        PROVIDER_HEALTH,
        PRIVACY_EXPORT
    }

    public enum ActionKind {
        KEEP,
        COMPACT,
        ARCHIVE,
        DELETE,
        HOLD
    }

    public static final class Rule {
        public final Category category;
        public final long hotRetentionMillis;
        public final long archiveRetentionMillis;
        public final int compactionFactor;
        public final boolean securityHoldEligible;

        public Rule(
                Category category,
                long hotRetentionMillis,
                long archiveRetentionMillis,
                int compactionFactor,
                boolean securityHoldEligible) {
            this.category = Objects.requireNonNull(category, "category");
            this.hotRetentionMillis = hotRetentionMillis;
            this.archiveRetentionMillis = archiveRetentionMillis;
            this.compactionFactor = compactionFactor;
            this.securityHoldEligible = securityHoldEligible;
            if (hotRetentionMillis <= 0 || archiveRetentionMillis < hotRetentionMillis) {
                throw new IllegalArgumentException("invalid retention interval");
            }
            if (compactionFactor <= 0) {
                throw new IllegalArgumentException("compaction factor must be positive");
            }
        }
    }

    public static final class Partition {
        public final String id;
        public final Category category;
        public final long firstEventAt;
        public final long lastEventAt;
        public final long eventCount;
        public final long bytes;
        public final boolean archived;
        public final boolean legalHold;

        public Partition(
                String id,
                Category category,
                long firstEventAt,
                long lastEventAt,
                long eventCount,
                long bytes,
                boolean archived,
                boolean legalHold) {
            this.id = require(id, "id");
            this.category = Objects.requireNonNull(category, "category");
            this.firstEventAt = firstEventAt;
            this.lastEventAt = lastEventAt;
            this.eventCount = eventCount;
            this.bytes = bytes;
            this.archived = archived;
            this.legalHold = legalHold;
            if (firstEventAt < 0
                    || lastEventAt < firstEventAt
                    || eventCount < 0
                    || bytes < 0) {
                throw new IllegalArgumentException("invalid partition metrics");
            }
        }
    }

    public static final class Action {
        public final String partitionId;
        public final ActionKind kind;
        public final String reason;
        public final long estimatedBytesAfter;
        public final long eventsAfter;

        Action(
                String partitionId,
                ActionKind kind,
                String reason,
                long estimatedBytesAfter,
                long eventsAfter) {
            this.partitionId = partitionId;
            this.kind = kind;
            this.reason = reason;
            this.estimatedBytesAfter = estimatedBytesAfter;
            this.eventsAfter = eventsAfter;
        }
    }

    public static final class Plan {
        public final List<Action> actions;
        public final long bytesBefore;
        public final long bytesAfter;
        public final long eventsBefore;
        public final long eventsAfter;

        Plan(
                List<Action> actions,
                long bytesBefore,
                long bytesAfter,
                long eventsBefore,
                long eventsAfter) {
            this.actions = Collections.unmodifiableList(new ArrayList<>(actions));
            this.bytesBefore = bytesBefore;
            this.bytesAfter = bytesAfter;
            this.eventsBefore = eventsBefore;
            this.eventsAfter = eventsAfter;
        }
    }

    private final Map<Category, Rule> rules;

    public AuditRetentionPlanner(Collection<Rule> rules) {
        Map<Category, Rule> indexed = new EnumMap<>(Category.class);
        for (Rule rule : Objects.requireNonNull(rules, "rules")) {
            if (indexed.put(rule.category, rule) != null) {
                throw new IllegalArgumentException("duplicate retention rule: " + rule.category);
            }
        }
        this.rules = Collections.unmodifiableMap(indexed);
    }

    public Plan plan(Collection<Partition> partitions, long now, long byteBudget) {
        if (now < 0 || byteBudget < 0) {
            throw new IllegalArgumentException("plan values must not be negative");
        }
        List<Partition> ordered = new ArrayList<>(
                Objects.requireNonNull(partitions, "partitions"));
        ordered.sort(Comparator.comparing((Partition value) -> value.category.name())
                .thenComparingLong(value -> value.lastEventAt)
                .thenComparing(value -> value.id));
        List<Action> actions = new ArrayList<>();
        long bytesBefore = 0;
        long bytesAfter = 0;
        long eventsBefore = 0;
        long eventsAfter = 0;
        for (Partition partition : ordered) {
            bytesBefore += partition.bytes;
            eventsBefore += partition.eventCount;
            Rule rule = rules.get(partition.category);
            Action action = decide(rule, partition, now, byteBudget, bytesAfter);
            actions.add(action);
            bytesAfter += action.estimatedBytesAfter;
            eventsAfter += action.eventsAfter;
        }
        return new Plan(
                actions,
                bytesBefore,
                bytesAfter,
                eventsBefore,
                eventsAfter);
    }

    private static Action decide(
            Rule rule,
            Partition partition,
            long now,
            long byteBudget,
            long bytesAlreadyKept) {
        if (rule == null) {
            return new Action(
                    partition.id,
                    ActionKind.HOLD,
                    "no retention rule",
                    partition.bytes,
                    partition.eventCount);
        }
        if (partition.legalHold) {
            return new Action(
                    partition.id,
                    ActionKind.HOLD,
                    "legal hold",
                    partition.bytes,
                    partition.eventCount);
        }
        long age = Math.max(0, now - partition.lastEventAt);
        if (age >= rule.archiveRetentionMillis) {
            return new Action(partition.id, ActionKind.DELETE, "retention elapsed", 0, 0);
        }
        if (partition.archived) {
            return new Action(
                    partition.id,
                    ActionKind.KEEP,
                    "within archive retention",
                    partition.bytes,
                    partition.eventCount);
        }
        if (age >= rule.hotRetentionMillis) {
            return new Action(
                    partition.id,
                    ActionKind.ARCHIVE,
                    "hot retention elapsed",
                    Math.max(1, partition.bytes / 2),
                    partition.eventCount);
        }
        if (bytesAlreadyKept + partition.bytes > byteBudget) {
            long compactedEvents = Math.max(1, partition.eventCount / rule.compactionFactor);
            long compactedBytes = Math.max(1, partition.bytes / rule.compactionFactor);
            return new Action(
                    partition.id,
                    ActionKind.COMPACT,
                    "byte budget pressure",
                    compactedBytes,
                    compactedEvents);
        }
        return new Action(
                partition.id,
                ActionKind.KEEP,
                "within hot retention",
                partition.bytes,
                partition.eventCount);
    }

    private static String require(String value, String name) {
        Objects.requireNonNull(value, name);
        if (value.trim().isEmpty()) {
            throw new IllegalArgumentException(name + " must not be empty");
        }
        return value;
    }
}

