package com.cockpitbench.foundation.tests;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.cockpitbench.foundation.core.CockpitClock;
import com.cockpitbench.foundation.core.WorkflowEngine;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public final class WorkflowEngineTest {
    @Test
    public void dependencyOrderAndOutputsAreDeterministic() {
        MutableClock clock = new MutableClock(100);
        WorkflowEngine engine = new WorkflowEngine(clock);
        List<String> observed = new ArrayList<>();
        engine.addObserver((execution, step, state) -> observed.add(step + ":" + state));
        WorkflowEngine.Step lookup = step(
                "lookup",
                Collections.emptyList(),
                context -> WorkflowEngine.ActionResult.success(
                        singleton("account", "driver-1")));
        WorkflowEngine.Step verify = step(
                "verify",
                Collections.singletonList("lookup"),
                context -> {
                    assertEquals("driver-1", context.require("account"));
                    return WorkflowEngine.ActionResult.success(
                            singleton("verified", "true"));
                });
        WorkflowEngine.Step audit = step(
                "audit",
                Collections.singletonList("verify"),
                context -> WorkflowEngine.ActionResult.success(
                        singleton("audit", context.require("verified"))));
        WorkflowEngine.Definition definition = new WorkflowEngine.Definition(
                "sign-in",
                4,
                Arrays.asList(audit, verify, lookup));

        WorkflowEngine.Execution execution = engine.start(
                "run-1",
                definition,
                Collections.emptyMap());

        assertEquals(WorkflowEngine.Status.COMPLETED, execution.status());
        assertEquals("true", execution.context.get("audit"));
        assertEquals("lookup:RUNNING", observed.get(0));
        assertEquals("audit:SUCCEEDED", observed.get(observed.size() - 1));
    }

    @Test
    public void waitingStepCanBeResumedWithUserInput() {
        MutableClock clock = new MutableClock(10);
        WorkflowEngine engine = new WorkflowEngine(clock);
        WorkflowEngine.Step consent = step(
                "consent",
                Collections.emptyList(),
                context -> WorkflowEngine.ActionResult.waiting(
                        "USER_CONSENT",
                        singleton("prompt", "privacy")));
        WorkflowEngine.Step persist = step(
                "persist",
                Collections.singletonList("consent"),
                context -> {
                    assertEquals("accepted", context.require("answer"));
                    return WorkflowEngine.ActionResult.success(Collections.emptyMap());
                });
        WorkflowEngine.Execution execution = engine.start(
                "run-2",
                new WorkflowEngine.Definition(
                        "consent-flow",
                        1,
                        Arrays.asList(consent, persist)),
                Collections.emptyMap());
        assertEquals(WorkflowEngine.Status.WAITING, execution.status());
        assertEquals("consent", execution.waitingStep());

        engine.resume(execution, "consent", singleton("answer", "accepted"));

        assertEquals(WorkflowEngine.Status.COMPLETED, execution.status());
        assertEquals(
                WorkflowEngine.StepStatus.SUCCEEDED,
                execution.stepStates().get("persist"));
    }

    @Test(expected = IllegalArgumentException.class)
    public void dependencyCyclesAreRejectedBeforeExecution() {
        WorkflowEngine.Step first = step(
                "first",
                Collections.singletonList("second"),
                context -> WorkflowEngine.ActionResult.success(Collections.emptyMap()));
        WorkflowEngine.Step second = step(
                "second",
                Collections.singletonList("first"),
                context -> WorkflowEngine.ActionResult.success(Collections.emptyMap()));
        new WorkflowEngine.Definition("cycle", 1, Arrays.asList(first, second));
    }

    private static WorkflowEngine.Step step(
            String id,
            List<String> dependencies,
            WorkflowEngine.Action action) {
        return new WorkflowEngine.Step(id, dependencies, 1_000, true, action);
    }

    private static Map<String, String> singleton(String key, String value) {
        Map<String, String> result = new LinkedHashMap<>();
        result.put(key, value);
        return result;
    }

    private static final class MutableClock implements CockpitClock {
        private long now;

        MutableClock(long now) {
            this.now = now;
        }

        @Override
        public long now() {
            return now;
        }
    }
}
