package com.cockpitbench.foundation.tests;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.cockpitbench.foundation.core.PolicyRuntime;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

public final class PolicyRuntimeTest {
    private final PolicyRuntime runtime = new PolicyRuntime();

    @Test
    public void explicitDenyPrecedesLowerPriorityGrant() {
        PolicyRuntime.Rule denyRearGuest = new PolicyRuntime.Rule(
                "deny-rear-guest",
                900,
                "account.remove",
                PolicyRuntime.Effect.DENY,
                Arrays.asList(
                        new PolicyRuntime.Condition(
                                "zone",
                                PolicyRuntime.Operator.EQUALS,
                                "rear_left"),
                        new PolicyRuntime.Condition(
                                "roles",
                                PolicyRuntime.Operator.CONTAINS,
                                "guest")),
                "guest occupants cannot remove accounts");
        PolicyRuntime.Rule ownerGrant = new PolicyRuntime.Rule(
                "owner-account-administration",
                500,
                "account.remove",
                PolicyRuntime.Effect.ALLOW,
                Collections.singletonList(new PolicyRuntime.Condition(
                        "roles",
                        PolicyRuntime.Operator.CONTAINS,
                        "owner")),
                "owner administers accounts");
        PolicyRuntime.PolicySet policy = new PolicyRuntime.PolicySet(
                "account-policy",
                7,
                PolicyRuntime.Effect.DENY,
                Arrays.asList(ownerGrant, denyRearGuest));

        PolicyRuntime.Decision decision = runtime.evaluate(
                policy,
                request("account.remove", "rear_left", "owner", "guest"));

        assertEquals(PolicyRuntime.Effect.DENY, decision.effect);
        assertEquals("deny-rear-guest", decision.ruleId);
        assertFalse(decision.permitsImmediateExecution());
        assertEquals(1, decision.trace.size());
    }

    @Test
    public void consentDecisionReportsInteractiveRequirement() {
        PolicyRuntime.Rule rule = new PolicyRuntime.Rule(
                "location-consent",
                100,
                "location.share",
                PolicyRuntime.Effect.REQUIRE_CONSENT,
                Arrays.asList(
                        new PolicyRuntime.Condition(
                                "purpose",
                                PolicyRuntime.Operator.IN,
                                "navigation,emergency"),
                        new PolicyRuntime.Condition(
                                "vehicleSpeed",
                                PolicyRuntime.Operator.LESS_THAN,
                                "1")),
                "location sharing requires a stopped-vehicle consent");
        PolicyRuntime.PolicySet policy = new PolicyRuntime.PolicySet(
                "privacy",
                2,
                PolicyRuntime.Effect.DENY,
                Collections.singletonList(rule));
        Map<String, String> attributes = new LinkedHashMap<>();
        attributes.put("purpose", "navigation");
        attributes.put("vehicleSpeed", "0");
        PolicyRuntime.Request request = new PolicyRuntime.Request(
                "location.share",
                "driver-1",
                10,
                "front",
                Collections.singleton("driver"),
                attributes);

        PolicyRuntime.Decision decision = runtime.evaluate(policy, request);

        assertTrue(decision.requiresUserInteraction());
        assertEquals(2, decision.policyRevision);
        assertEquals("location-consent", decision.ruleId);
    }

    @Test
    public void batchKeysIncludeAccountOperationAndZone() {
        PolicyRuntime.PolicySet policy = new PolicyRuntime.PolicySet(
                "default-deny",
                1,
                PolicyRuntime.Effect.DENY,
                Collections.emptyList());
        Map<String, PolicyRuntime.Decision> decisions = runtime.evaluateBatch(
                policy,
                Arrays.asList(
                        request("role.read", "front", "driver"),
                        request("role.read", "rear_left", "passenger")));

        assertEquals(2, decisions.size());
        assertTrue(decisions.containsKey("account-1:role.read:front"));
        assertTrue(decisions.containsKey("account-1:role.read:rear_left"));
    }

    private static PolicyRuntime.Request request(
            String operation,
            String zone,
            String... roles) {
        return new PolicyRuntime.Request(
                operation,
                "account-1",
                10,
                zone,
                Arrays.asList(roles),
                Collections.emptyMap());
    }
}
