package com.cockpitbench.foundation.tests;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.cockpitbench.foundation.core.RoleAuthorizationGraph;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public final class RoleAuthorizationGraphTest {
    @Test
    public void childDenyOverridesInheritedPassengerGrant() {
        RoleAuthorizationGraph graph = graph();
        RoleAuthorizationGraph.Decision decision = graph.authorize(
                Collections.singletonList(new RoleAuthorizationGraph.Assignment(
                        "child",
                        "rear_left",
                        0,
                        1_000,
                        "family")),
                "media.purchase",
                "rear_left",
                true,
                100);

        assertFalse(decision.allowed);
        assertEquals("explicit deny from child", decision.reason);
        assertTrue(decision.effectiveRoles.contains("passenger"));
        assertTrue(decision.effectiveRoles.contains("child"));
    }

    @Test
    public void ownerGrantRequiresRecentAuthentication() {
        RoleAuthorizationGraph graph = graph();
        RoleAuthorizationGraph.Assignment owner = new RoleAuthorizationGraph.Assignment(
                "owner",
                "all",
                0,
                1_000,
                "provisioning");

        RoleAuthorizationGraph.Decision stale = graph.authorize(
                Collections.singletonList(owner),
                "account.remove",
                "front",
                false,
                100);
        RoleAuthorizationGraph.Decision recent = graph.authorize(
                Collections.singletonList(owner),
                "account.remove",
                "front",
                true,
                100);

        assertTrue(stale.reauthenticationRequired);
        assertFalse(stale.allowed);
        assertTrue(recent.allowed);
    }

    @Test
    public void expiredAssignmentContributesNoRoles() {
        RoleAuthorizationGraph graph = graph();
        RoleAuthorizationGraph.Decision decision = graph.authorize(
                Collections.singletonList(new RoleAuthorizationGraph.Assignment(
                        "passenger",
                        "rear_right",
                        0,
                        10,
                        "temporary")),
                "media.browse",
                "rear_right",
                true,
                20);

        assertFalse(decision.allowed);
        assertTrue(decision.effectiveRoles.isEmpty());
    }

    @Test
    public void inheritanceOrderPlacesAncestorBeforeAssignedRole() {
        assertEquals(
                Arrays.asList("passenger", "child"),
                graph().inheritanceOrder("child"));
    }

    private static RoleAuthorizationGraph graph() {
        RoleAuthorizationGraph.Permission browse = new RoleAuthorizationGraph.Permission(
                "media.browse",
                RoleAuthorizationGraph.Effect.ALLOW,
                Collections.singletonList("all"),
                false);
        RoleAuthorizationGraph.Permission purchase = new RoleAuthorizationGraph.Permission(
                "media.purchase",
                RoleAuthorizationGraph.Effect.ALLOW,
                Collections.singletonList("rear_left"),
                false);
        RoleAuthorizationGraph.Permission childDeny = new RoleAuthorizationGraph.Permission(
                "media.purchase",
                RoleAuthorizationGraph.Effect.DENY,
                Collections.singletonList("all"),
                false);
        RoleAuthorizationGraph.Permission remove = new RoleAuthorizationGraph.Permission(
                "account.remove",
                RoleAuthorizationGraph.Effect.ALLOW,
                Collections.singletonList("all"),
                true);
        RoleAuthorizationGraph.Role passenger = new RoleAuthorizationGraph.Role(
                "passenger",
                Collections.emptyList(),
                Arrays.asList(browse, purchase),
                true);
        RoleAuthorizationGraph.Role child = new RoleAuthorizationGraph.Role(
                "child",
                Collections.singletonList("passenger"),
                Collections.singletonList(childDeny),
                true);
        RoleAuthorizationGraph.Role owner = new RoleAuthorizationGraph.Role(
                "owner",
                Collections.emptyList(),
                Collections.singletonList(remove),
                true);
        return new RoleAuthorizationGraph(Arrays.asList(passenger, child, owner));
    }
}

