package com.cockpitbench.foundation.tests;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.cockpitbench.foundation.core.RecordReconciler;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

public final class RecordReconcilerTest {
    @Test
    public void authorityPolicyChoosesOwnerDisplayName() {
        RecordReconciler reconciler = new RecordReconciler(
                Collections.singletonList(new RecordReconciler.FieldPolicy(
                        "displayName",
                        RecordReconciler.Strategy.AUTHORITY,
                        Arrays.asList(
                                RecordReconciler.Authority.OWNER,
                                RecordReconciler.Authority.PROVIDER,
                                RecordReconciler.Authority.LOCAL),
                        false)));
        RecordReconciler.Record base = record(
                3,
                "displayName",
                value("Driver", 10, RecordReconciler.Authority.PROVIDER));
        RecordReconciler.Record local = record(
                4,
                "displayName",
                value("Local", 30, RecordReconciler.Authority.LOCAL));
        RecordReconciler.Record remote = record(
                5,
                "displayName",
                value("Owner", 20, RecordReconciler.Authority.OWNER));

        RecordReconciler.Result result = reconciler.reconcile(base, local, remote);

        assertEquals("Owner", result.merged.fields.get("displayName").content);
        assertEquals(6, result.merged.revision);
        assertFalse(result.requiresUserResolution());
        assertEquals("remote-authority", result.changes.get(0).source);
    }

    @Test
    public void manualStrategyPreservesProvisionalValueAndConflict() {
        RecordReconciler reconciler = new RecordReconciler(
                Collections.singletonList(new RecordReconciler.FieldPolicy(
                        "avatar",
                        RecordReconciler.Strategy.MANUAL,
                        Collections.emptyList(),
                        false)));
        RecordReconciler.Record base = record(
                1,
                "avatar",
                value("base.png", 1, RecordReconciler.Authority.LOCAL));
        RecordReconciler.Record local = record(
                2,
                "avatar",
                value("local.png", 5, RecordReconciler.Authority.LOCAL));
        RecordReconciler.Record remote = record(
                2,
                "avatar",
                value("remote.png", 8, RecordReconciler.Authority.PROVIDER));

        RecordReconciler.Result result = reconciler.reconcile(base, local, remote);

        assertTrue(result.requiresUserResolution());
        assertEquals("remote.png", result.merged.fields.get("avatar").content);
        assertEquals("avatar", result.conflicts.get(0).field);
    }

    @Test
    public void deletionWinsRemovesMergedField() {
        RecordReconciler reconciler = new RecordReconciler(
                Collections.singletonList(new RecordReconciler.FieldPolicy(
                        "phone",
                        RecordReconciler.Strategy.NEWEST,
                        Collections.emptyList(),
                        true)));
        RecordReconciler.Value baseValue = value(
                "123",
                1,
                RecordReconciler.Authority.OWNER);
        RecordReconciler.Record base = record(1, "phone", baseValue);
        RecordReconciler.Record local = record(
                2,
                "phone",
                new RecordReconciler.Value(
                        "",
                        2,
                        RecordReconciler.Authority.OWNER,
                        true));
        RecordReconciler.Record remote = record(
                3,
                "phone",
                value("456", 3, RecordReconciler.Authority.PROVIDER));

        RecordReconciler.Result result = reconciler.reconcile(base, local, remote);

        assertFalse(result.merged.fields.containsKey("phone"));
        assertEquals("deletion", result.changes.get(0).source);
    }

    private static RecordReconciler.Record record(
            long revision,
            String field,
            RecordReconciler.Value value) {
        Map<String, RecordReconciler.Value> fields = new LinkedHashMap<>();
        fields.put(field, value);
        return new RecordReconciler.Record("account-1", revision, fields);
    }

    private static RecordReconciler.Value value(
            String content,
            long changedAt,
            RecordReconciler.Authority authority) {
        return new RecordReconciler.Value(content, changedAt, authority, false);
    }
}
