package com.cockpitbench.foundation.tests;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.cockpitbench.foundation.core.DeviceTrustEngine;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import org.junit.Test;

public final class DeviceTrustEngineTest {
    @Test
    public void freshRequiredSignalsReachTrustedVerdict() {
        DeviceTrustEngine.Policy policy = policy(true);
        DeviceTrustEngine engine = new DeviceTrustEngine();
        DeviceTrustEngine.Assessment result = engine.assess(
                policy,
                Arrays.asList(
                        signal(DeviceTrustEngine.SignalKind.HARDWARE_ATTESTATION, true, 100, 900),
                        signal(DeviceTrustEngine.SignalKind.SECURE_CHANNEL, true, 100, 950),
                        signal(DeviceTrustEngine.SignalKind.VEHICLE_KEY, true, 90, 980),
                        signal(DeviceTrustEngine.SignalKind.TAMPER_DETECTION, true, 100, 990)),
                1_000);

        assertEquals(DeviceTrustEngine.Verdict.TRUSTED, result.verdict);
        assertTrue(result.permitsCredentialRelease());
        assertTrue(result.missingRequired.isEmpty());
        assertEquals(4, result.evidence.size());
    }

    @Test
    public void staleAttestationProducesChallenge() {
        DeviceTrustEngine engine = new DeviceTrustEngine();
        DeviceTrustEngine.Assessment result = engine.assess(
                policy(false),
                Arrays.asList(
                        signal(DeviceTrustEngine.SignalKind.HARDWARE_ATTESTATION, true, 100, 1),
                        signal(DeviceTrustEngine.SignalKind.SECURE_CHANNEL, true, 100, 990)),
                1_000);

        assertEquals(DeviceTrustEngine.Verdict.CHALLENGE_REQUIRED, result.verdict);
        assertTrue(result.missingRequired.contains(
                DeviceTrustEngine.SignalKind.HARDWARE_ATTESTATION));
        assertFalse(result.permitsCredentialRelease());
    }

    @Test
    public void currentTamperFailureRejectsRegardlessOfScore() {
        DeviceTrustEngine engine = new DeviceTrustEngine();
        DeviceTrustEngine.Assessment result = engine.assess(
                policy(true),
                Arrays.asList(
                        signal(DeviceTrustEngine.SignalKind.HARDWARE_ATTESTATION, true, 100, 990),
                        signal(DeviceTrustEngine.SignalKind.SECURE_CHANNEL, true, 100, 990),
                        signal(DeviceTrustEngine.SignalKind.VEHICLE_KEY, true, 100, 990),
                        signal(DeviceTrustEngine.SignalKind.TAMPER_DETECTION, false, 100, 990)),
                1_000);

        assertEquals(DeviceTrustEngine.Verdict.REJECTED, result.verdict);
        assertFalse(result.permitsLimitedSession());
    }

    @Test
    public void fleetAssessmentIsSortedByDeviceId() {
        DeviceTrustEngine engine = new DeviceTrustEngine();
        Map<String, java.util.List<DeviceTrustEngine.Signal>> evidence =
                new java.util.LinkedHashMap<>();
        evidence.put("device-z", Collections.singletonList(
                signal(DeviceTrustEngine.SignalKind.SECURE_CHANNEL, true, 100, 10)));
        evidence.put("device-a", Collections.singletonList(
                signal(DeviceTrustEngine.SignalKind.SECURE_CHANNEL, true, 100, 10)));

        Map<String, DeviceTrustEngine.Assessment> result =
                engine.assessFleet(policy(false), evidence, 20);

        assertEquals("device-a", result.keySet().iterator().next());
    }

    private static DeviceTrustEngine.Policy policy(boolean rejectTamper) {
        Map<DeviceTrustEngine.SignalKind, Integer> weights =
                new EnumMap<>(DeviceTrustEngine.SignalKind.class);
        weights.put(DeviceTrustEngine.SignalKind.HARDWARE_ATTESTATION, 35);
        weights.put(DeviceTrustEngine.SignalKind.SECURE_CHANNEL, 25);
        weights.put(DeviceTrustEngine.SignalKind.VEHICLE_KEY, 25);
        weights.put(DeviceTrustEngine.SignalKind.TAMPER_DETECTION, 20);
        return new DeviceTrustEngine.Policy(
                "owner-device",
                500,
                70,
                rejectTamper ? 35 : -20,
                Arrays.asList(
                        DeviceTrustEngine.SignalKind.HARDWARE_ATTESTATION,
                        DeviceTrustEngine.SignalKind.SECURE_CHANNEL),
                weights,
                rejectTamper);
    }

    private static DeviceTrustEngine.Signal signal(
            DeviceTrustEngine.SignalKind kind,
            boolean passed,
            int confidence,
            long observedAt) {
        return new DeviceTrustEngine.Signal(kind, passed, confidence, observedAt, "test");
    }
}
