package com.cockpitbench.foundation.tests;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.cockpitbench.foundation.core.ProviderHealthMonitor;
import org.junit.Test;

public final class ProviderHealthMonitorTest {
    @Test
    public void repeatedInfrastructureFailuresOpenCircuit() {
        ProviderHealthMonitor monitor = monitor();
        monitor.record("cloud", sample(ProviderHealthMonitor.Outcome.NETWORK_ERROR, 50, 1));
        monitor.record("cloud", sample(ProviderHealthMonitor.Outcome.TIMEOUT, 200, 2));
        monitor.record("cloud", sample(ProviderHealthMonitor.Outcome.SUCCESS, 20, 3));
        monitor.record("cloud", sample(ProviderHealthMonitor.Outcome.PROVIDER_ERROR, 40, 4));

        ProviderHealthMonitor.Health health = monitor.health("cloud", 5);

        assertEquals(ProviderHealthMonitor.CircuitState.OPEN, health.state);
        assertEquals(3, health.failures);
        assertEquals(0.75, health.failureRate, 0.001);
        assertFalse(monitor.acquire("cloud", 5));
    }

    @Test
    public void openCircuitTransitionsThroughHalfOpenProbe() {
        ProviderHealthMonitor monitor = monitor();
        monitor.record("fleet", sample(ProviderHealthMonitor.Outcome.TIMEOUT, 100, 1));
        monitor.record("fleet", sample(ProviderHealthMonitor.Outcome.TIMEOUT, 100, 2));
        monitor.record("fleet", sample(ProviderHealthMonitor.Outcome.TIMEOUT, 100, 3));

        assertTrue(monitor.acquire("fleet", 200));
        assertFalse(monitor.acquire("fleet", 200));
        monitor.record("fleet", sample(ProviderHealthMonitor.Outcome.SUCCESS, 10, 201));
        assertTrue(monitor.acquire("fleet", 202));
        monitor.record("fleet", sample(ProviderHealthMonitor.Outcome.SUCCESS, 10, 203));

        assertEquals(
                ProviderHealthMonitor.CircuitState.CLOSED,
                monitor.health("fleet", 204).state);
    }

    @Test
    public void authenticationRejectionDoesNotCountAsProviderFailure() {
        ProviderHealthMonitor monitor = monitor();
        monitor.record("pin", sample(
                ProviderHealthMonitor.Outcome.AUTHENTICATION_REJECTED,
                10,
                1));
        monitor.record("pin", sample(
                ProviderHealthMonitor.Outcome.AUTHENTICATION_REJECTED,
                12,
                2));
        monitor.record("pin", sample(ProviderHealthMonitor.Outcome.SUCCESS, 8, 3));

        ProviderHealthMonitor.Health health = monitor.health("pin", 4);

        assertEquals(0, health.failures);
        assertEquals(ProviderHealthMonitor.CircuitState.CLOSED, health.state);
        assertEquals(10, health.medianLatencyMillis);
    }

    @Test
    public void latencyPercentileCanOpenOtherwiseSuccessfulProvider() {
        ProviderHealthMonitor monitor = monitor();
        monitor.record("sso", sample(ProviderHealthMonitor.Outcome.SUCCESS, 10, 1));
        monitor.record("sso", sample(ProviderHealthMonitor.Outcome.SUCCESS, 20, 2));
        monitor.record("sso", sample(ProviderHealthMonitor.Outcome.SUCCESS, 200, 3));

        ProviderHealthMonitor.Health health = monitor.health("sso", 4);

        assertEquals(200, health.percentile95LatencyMillis);
        assertEquals(ProviderHealthMonitor.CircuitState.OPEN, health.state);
    }

    private static ProviderHealthMonitor monitor() {
        return new ProviderHealthMonitor(new ProviderHealthMonitor.Config(
                5,
                3,
                0.60,
                100,
                100,
                2));
    }

    private static ProviderHealthMonitor.Sample sample(
            ProviderHealthMonitor.Outcome outcome,
            long latency,
            long time) {
        return new ProviderHealthMonitor.Sample(outcome, latency, time);
    }
}
