package com.cockpitbench.foundation.tests;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.cockpitbench.foundation.core.SessionSupervisor;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public final class SessionSupervisorTest {
    @Test
    public void openTouchTransferAndRevokePublishOrderedEvents() {
        SessionSupervisor supervisor = supervisor();
        List<SessionSupervisor.EventType> events = new ArrayList<>();
        supervisor.addObserver(event -> events.add(event.type));
        SessionSupervisor.Session session = supervisor.open(
                "session-1",
                "account-1",
                10,
                "front",
                100);
        supervisor.touch("session-1", 120);
        supervisor.transfer("session-1", "rear_left", 130);
        supervisor.revoke("session-1", "sign out", 140);

        assertEquals(SessionSupervisor.State.REVOKED, session.state());
        assertEquals("rear_left", session.zone());
        assertEquals(4, events.size());
        assertEquals(SessionSupervisor.EventType.OPENED, events.get(0));
        assertEquals(SessionSupervisor.EventType.REVOKED, events.get(3));
    }

    @Test
    public void idleSessionExpiresAndCanBeRemoved() {
        SessionSupervisor supervisor = supervisor();
        supervisor.open("session-2", "account-2", 10, "front", 0);

        assertEquals(1, supervisor.expire(101));
        assertEquals(SessionSupervisor.State.EXPIRED, supervisor.snapshot().get(0).state());
        assertEquals(1, supervisor.removeTerminal());
        assertTrue(supervisor.snapshot().isEmpty());
    }

    @Test
    public void reauthenticationRestoresSuspendedSession() {
        SessionSupervisor supervisor = supervisor();
        supervisor.open("session-3", "account-3", 10, "front", 0);
        supervisor.requireReauthentication("session-3", "sensitive operation", 10);

        supervisor.reauthenticated("session-3", 20);

        SessionSupervisor.Session session = supervisor.snapshot().get(0);
        assertEquals(SessionSupervisor.State.ACTIVE, session.state());
        assertEquals(20, session.lastActiveAt());
    }

    @Test(expected = IllegalStateException.class)
    public void accountCapacityIsEnforced() {
        SessionSupervisor supervisor = supervisor();
        supervisor.open("session-4", "account-4", 10, "front", 0);
        supervisor.open("session-5", "account-4", 10, "rear_left", 1);
        supervisor.open("session-6", "account-4", 10, "rear_right", 2);
    }

    private static SessionSupervisor supervisor() {
        return new SessionSupervisor(new SessionSupervisor.Limits(
                2,
                2,
                100,
                1_000,
                50));
    }
}

